comms.text:
@1 וּמַלִּיל יְיָ עִם משֶׁה בְּטוּרָא דְסִינַי לְמֵימָר:
@2 מַלֵּיל עִם בְּנֵי יִשְׂרָאֵל וְתֵימַר לְהוֹן אֲרֵי תֵעֲלוּן לְאַרְעָא דִּי אֲנָא יָהֵב לְכוֹן וְתַשְׁמֵט אַרְעָא שְׁמִטְּתָא קֳדָם יְיָ:
@3 שִׁית שְׁנִין תִּזְרַע חַקְלָךְ וְשִׁית שְׁנִין תִּכְסַח כַּרְמָךְ וְתִכְנוֹשׁ יָת עֲלַלְתַּהּ:
@4 וּבְשַׁתָּא שְׁבִיעֲתָא נְיַח שְׁמִטְּתָא יְהֵי לְאַרְעָא דְּתַשְׁמֵט קֳדָם יְיָ חַקְלָךְ לָא תִזְרַע וְכַרְמָךְ לָא תִכְסָח:
@5 יָת כַּתֵּי דַחֲצָדָךְ לָא תֶחֱצַד וְיָת עִנְּבֵי שִׁבְקָךְ לָא תִקְטוֹף שְׁנַת שְׁמִטְּתָא יְהֵי לְאַרְעָא:
@6 וּתְהֵי שְׁמִטַּת אַרְעָא לְכוֹן לְמֵיכַל לָךְ וּלְעַבְדָּךְ וּלְאַמְתָךְ וְלַאֲגִירָךְ וּלְתוֹתָבָךְ דְּדָיְרִין עִמָּךְ:
@7 וְלִבְעִירָךְ וּלְחַיְתָא דִּי בְאַרְעָךְ תְּהֵי כָל עֲלַלְתַּהּ לְמֵיכָל:
@8 וְתִמְנֵי לָךְ שְׁבַע שְׁמִטִּין דִּשְׁנִין שְׁבַע שְׁנִין שְׁבַע זִמְנִין וִיהוֹן לָךְ יוֹמֵי שְׁבַע שְׁמִטִּין דִּשְׁנִין אַרְבְּעִין וְתֵשַׁע שְׁנִין:
@9 וְתַעֲבַר שׁוֹפַר יַבָּבָא בְּיַרְחָא שְׁבִיעָאָה בְּעַשְׂרָא לְיַרְחָא בְּיוֹמָא דְכִפּוּרַיָּא תַּעַבְּרוּן שׁוֹפָרָא בְּכָל אַרְעֲכוֹן:
@10 וּתְקַדְּשׁוּן יָת שְׁנַת חַמְשִׁין שְׁנִין וְתַקְרוּן חֵרוּתָא בְּאַרְעָא לְכָל יָתְבָהָא יוֹבֵלָא הִיא תְּהֵי לְכוֹן וּתְתוּבוּן גְּבַר לְאַחֲסַנְתֵּיהּ וּגְבַר לְזַרְעִיתֵיהּ תְּתוּבוּן:
@11 יוֹבֵלָא הִיא שְׁנַת חַמְשִׁין שְׁנִין תְּהֵי לְכוֹן לָא תִזְרְעוּן וְלָא תַחְצְדוּן יָת כַּתָּהָא וְלָא תִקְטְפוּן יָת שִׁבְקָהָא:
@12 אֲרֵי יוֹבֵלָא הִיא קוּדְשָׁא תְהֵי לְכוֹן מִן חַקְלָא תֵּיכְלוּן יָת עֲלַלְתַּהּ:
@13 בְּשַׁתָּא דְיוֹבֵלָא הָדָא תְּתוּבוּן גְּבַר לְאַחֲסַנְתֵּיהּ:
@14 וַאֲרֵי תְזַבֵּן זְבִינִין לְחַבְרָךְ אוֹ תִזְבֵּן מִידָא דְחַבְרָךְ לָא תוֹנוּן גְּבַר יָת אֲחוֹהִי:
@15 בְּמִנְיַן שְׁנַיָּא בָּתַר יוֹבֵלָא תִּזְבֵּן מִן חַבְרָךְ בְּמִנְיַן שְׁנֵי עֲלַלְתָּא יְזַבֶּן לָךְ:
@16 לְפוּם סְגִיאוּת שְׁנַיָּא תַּסְגֵּי זְבִינוֹהִי וּלְפוּם זְעֵרוּת שְׁנַיָּא תַּזְעֵר זְבִינוֹהִי אֲרֵי מִנְיַן עֲלַלְתָּא הוּא מְזַבֵּן לָךְ:
@17 וְלָא תוֹנוּן גְּבַר יָת חַבְרֵיהּ וְתִדְחַל מֵאֱלָהָךְ אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@18 וְתַעְבְּדוּן יָת קְיָמַי וְיָת דִּינַי תִּטְּרוּן וְתַעְבְּדוּן יָתְהוֹן וְתֵיתְבוּן עַל אַרְעָא לְרָחְצָן:
@19 וְתִתֵּן אַרְעָא אִבַּהּ וְתֵיכְלוּן לְמִשְׂבָּע וְתֵיתְבוּן לְרָחֲצָן עֲלַהּ:
@20 וַאֲרֵי תֵימְרוּן מָא נֵיכוּל בְּשַׁתָּא שְׁבִיעֵתָא הָא לָא נִזְרָע וְלָא נִכְנוֹשׁ יָת עֲלַלְתָּנָא:
@21 וֶאֱפַקֵּד יָת בִּרְכָתִי לְכוֹן בְּשַׁתָּא שְׁתִיתֵתָא וְתַעְבֵּד יָת עֲלַלְתָּא לִתְלַת שְׁנִין:
@22 וְתִזְרְעוּן יָת שַׁתָּא תְמִינֵתָא וְתֵיכְלוּן מִן עֲלַלְתָּא עַתִּיקָא עַד שַׁתָּא תְשִׁיעֵתָא עַד מֵעַל עֲלַלְתַּהּ תֵּיכְלוּן עַתִּיקָא:
@23 וְאַרְעָא לָא תִזְדַּבַּן לַחֲלוּטִין אֲרֵי דִילִי אַרְעָא אֲרֵי דַיָּרִין וְתוֹתָבִין אַתּוּן קֳדָמַי:
@24 וּבְכֹל אַרְעָא אַחֲסַנְתְּכוֹן פֻּרְקָנָא תִּתְּנוּן לְאַרְעָא:
@25 אֲרֵי יְתְמַסְכַּן אָחוּךְ וִיזַבֵּן מֵאַחֲסַנְתֵּהּ וְיֵיתֵי פָרִיקֵיהּ דְּקָרִיב לֵיהּ וְיִפְרוֹק יָת זְבִינֵי אֲחוּהִי:
@26 וּגְבַר אֲרֵי לָא יְהֵי לֵהּ פָּרִיק וְתַדְבֵּק יְדֵהּ וְיַשְׁכַּח כְּמִסַּת פֻּרְקָנֵהּ:
@27 וִיחַשֵּׁב יָת שְׁנֵי זְבִינוֹהִי וְיָתֵב יָת מוֹתָרָא לִגְבַר דִּי זַבֶּן לֵיהּ וִיתוּב לְאַחֲסַנְתֵּהּ:
@28 וְאִם לָא תַשְׁכַּח יְדֵהּ כְּמִסַּת אֲתֵב לֵיהּ וִיהֵי זְבִינוֹהִי בִּידָא דִּזְבַן יָתֵיהּ עַד שַׁתָּא דְיוֹבֵלָא וְיִפּוֹק בְּיוֹבֵלָא וִיתוּב לְאַחֲסַנְתֵּיהּ:
@29 וּגְבַר אֲרֵי יְזַבֵּן בֵּית מוֹתַב קַרְתָּא מַקְּפָא שׁוּר וּתְהֵי פֻרְקָנֵיהּ עַד מִשְׁלַם שַׁתָּא דִזְבִינוֹהִי עִדָּן בְּעִדָּן תְּהֵי פֻרְקָנֵיהּ:
@30 וְאִם לָא יִתְפָּרַק עַד מִשְׁלַם לֵיהּ שַׁתָּא שְׁלֶמְתָּא וִיקוּם בֵּיתָא דִי בְקַרְתָּא דִּי לֵיהּ שׁוּרָא לַחֲלוּטִין לְדִי זְבַן יָתֵיהּ לְדָרוֹהִי לָא יִפּוֹק בְּיוֹבֵלָא:
@31 וּבָתֵּי פַצְחַיָּא דִּי לֵית לְהוֹן שׁוּר מַקַּף סְחוֹר סְחוֹר עַל חֲקַל אַרְעָא יִתְחַשָּׁב פֻּרְקָנָא תְּהֵי לֵיהּ וּבְיוֹבֵלָא יִפּוֹק:
@32 וְקִרְוֵי לֵיוָאֵי בָּתֵּי קִרְוֵי אַחֲסַנְתְּהוֹן פֻּרְקַן עָלָם תְּהֵי לְלֵיוָאֵי:
@33 וְדִי יִפְרוֹק מִן לֵיוָאֵי וְיִפּוֹק זְבִין בֵּיתָא וְקַרְתָּא אַחֲסַנְתֵּיהּ בְּיוֹבֵלָא אֲרֵי בָתֵּי קִרְוֵי לֵיוָאֵי הִיא אַחֲסַנְתְּהוֹן בְּגוֹ בְּנֵי יִשְׂרָאֵל:
@34 וַחֲקַל רְוַח קִרְוֵיהוֹן לָא יִזְדַּבָּן אֲרֵי אַחֲסָנַת עָלָם הוּא לְהוֹן:
@35 וַאֲרֵי יִתְמַסְכַּן אָחוּךְ וּתְמוּט יְדֵיהּ עִמָּךְ וְתַתְקֵף בֵּיהּ דַּיַּר וְתוֹתָב וִיחֵי עִמָּךְ:
@36 לָא תִסַּב מִנֵּיהּ חִבּוּלְיָא וְרִבִּיתָא וְתִדְחַל מֵאֱלָהָךְ וִיחֵי אָחוּךְ עִמָּךְ:
@37 יָת כַּסְפָּךְ לָא תִתֵּן לֵיהּ בְּחִבּוּלְיָא וּבְרִבִּיתָא לָא תִתֵּן מֵיכְלָךְ:
@38 אֲנָא יְיָ אֱלָהָכוֹן דִּי אַפֵּקִית יָתְכוֹן מֵאַרְעָא דְמִצְרָיִם לְמִתַּן לְכוֹן יָת אַרְעָא דִכְנַעַן לְמֶהֱוֵי לְכוֹן לֶאֱלָהּ:
@39 וַאֲרֵי יִתְמַסְכַּן אָחוּךְ עִמָּךְ וְיִזְדַּבַּן לָךְ לָא תִפְלַח בֵּיהּ פָּלְחַן עַבְדִּין:
@40 כַּאֲגִירָא כְתוֹתָבָא יְהֵי עִמָּךְ עַד שַׁתָּא דְיוֹבֵלָא יִפְלַח עִמָּךְ:
@41 וְיִפּוֹק מֵעִמָּךְ הוּא וּבְנוֹהִי עִמֵּיהּ וִיתוּב לְזַרְעִיתֵיהּ וּלְאַחֲסָנַת אֲבָהָתוֹהִי יְתוּב:
@42 אֲרֵי עַבְדַּי אִנּוּן דִּי אַפֵּקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם לָא יִזְדַּבְּנוּן זְבוּן עַבְדִּין:
@43 לָא תִפְלַח בֵּיהּ בְּקַשְׁיוּ וְתִדְחַל מֵאֱלָהָךְ:
@44 וְעַבְדָּךְ וְאַמְתָךְ דִּי יְהוֹן לָךְ מִן עַמְמַיָּא דִּי בְסַחֲרָנֵיכוֹן מִנְּהוֹן תִּקְנוּן עַבְדִּין וְאַמְהָן:
@45 וְאַף מִבְּנֵי תוֹתָבַיָּא עָרְלַיָּא דְּדָיְרִין עִמְּכוֹן מִנְּהוֹן תִּקְנוּן וּמִזַּרְעִיתְהוֹן דְּעִמְּכוֹן דִּי אִתְיְלִידוּ בְּאַרְעֲכוֹן וִיהוֹן לְכוֹן לְאַחֲסָנָא:
@46 וְתַחְסְנוּן יָתְהוֹן לִבְנֵיכוֹן בַּתְרֵיכוֹן לִירוּתַת אַחֲסָנָא לְעָלָם בְּהוֹן תִּפְלְחוּן וּבְאַחֵיכוֹן בְּנֵי יִשְׂרָאֵל גְּבַר בַּאֲחוּהִי לָא תִפְלַח בֵּיהּ בְּקַשְׁיוּ:
@47 וַאֲרֵי תַדְבֵּק יַד עָרֵל וְתוֹתָב עִמָּךְ וְיִתְמַסְכַּן אָחוּךְ עִמֵּיהּ וְיִזְדַּבַּן לְעָרֵל תּוֹתָב עִמָּךְ אוֹ לְאַרְמַי זַרְעִית גִּיּוֹרָא:
@48 בָּתַר דְּיִזְדַּבַּן פֻּרְקָנָא תְּהֵי לֵיהּ חַד מֵאֲחוֹהִי יִפְרְקִנֵּיהּ:
@49 אוֹ אַח אֲבוּהִי אוֹ בַר אַח אֲבוּהִי יִפְרְקִנֵּיהּ אוֹ מִקָּרִיב בִּשְׂרֵיהּ מִזַּרְעִיתֵיהּ יִפְרְקִנֵּיהּ אוֹ דְתַדְבֵּק יְדֵיהּ וְיִתְפָּרָק:
@50 וִיחַשֵּׁב עִם זָבְנֵיהּ מִשַּׁתָּא דְּאִזְדַּבַּן לֵיהּ עַד שַׁתָּא דְיוֹבֵלָא וִיהֵי כְּסַף זְבִינוֹהִי בְּמִנְיַן שְׁנַיָא כְּיוֹמֵי אֲגִירָא יְהֵי עִמֵּיהּ:
@51 אִם עוֹד סְגִיּוּת בִּשְׁנַיָּא לְפוּמְהֵן יָתֵיב פֻּרְקָנֵיהּ מִכְּסַף זְבִינוֹהִי:
@52 וְאִם זְעֵר יִשְׁתָּאַר בִּשְׁנַיָּא עַד שַׁתָּא דְיוֹבֵלָא וִיחַשֵּׁב לֵיהּ כְּפוּם שְׁנוֹהִי יָתֵב יָת פֻּרְקָנֵיהּ:
@53 כַּאֲגִיר שְׁנָא בִּשְׁנָא יְהֵי עִמֵּיהּ לָא יִפְלַח בֵּיהּ בְּקַשְׁיוּ לְעֵינָיךְ:
@54 וְאִם לָא יִתְפָּרַק בְּאִלֵּין וְיִפּוֹק בְּשַׁתָּא דְיוֹבֵלָא הוּא וּבְנוֹהִי עִמֵּיהּ:
@55 אֲרֵי דִילִי בְנֵי יִשְׂרָאֵל עַבְדִּין עַבְדַּי אִנּוּן דִּי אֲפֵּיקִית יָתְהוֹן מֵאַרְעָא דְמִצְרָיִם אֲנָא יְיָ אֱלָהָכוֹן:
@56 לָא תַעְבְּדוּן לְכוֹן טַעֲוָן וְצֶלֶם וְקָמָא לָא תְקִימוּן לְכוֹן וְאֶבֶן סָגְדָא לָא תִתְּנוּן בְּאַרְעֲכוֹן לְמִסְגֻּד עֲלַהּ אֲרֵי אֲנָא יְיָ אֱלָהָכוֹן:
@57 יָת יוֹמֵי שַׁבַּיָּא דִילִי תִטְּרוּן וּלְבֵית מַקְדְּשִׁי תְּהוֹן דָּחֲלִין אֲנָא יְיָ:

@1 **בהר סיני.** מָה עִנְיַן שְׁמִטָּה אֵצֶל הַר סִינַי? וַהֲלֹא כָל הַמִּצְוֹת נֶאֶמְרוּ מִסִּינַי? אֶלָּא מַה שְּׁמִטָּה נֶאֶמְרוּ כְלָלוֹתֶיהָ וּפְרָטוֹתֶיהָ וְדִקְדּוּקֶיהָ מִסִּינַי אַף כֻּלָּן נֶאֶמְרוּ כְלָלוֹתֵיהֶן וְדִקְדּוּקֵיהֶן מִסִּינַי, כָּךְ שְׁנוּיָה בְּתֹ"כֹּ; וְנִרְאֶה לִי שֶׁכָּךְ פֵּרוּשָׁהּ: לְפִי שֶׁלֹּא מָצִינוּ שְׁמִטַּת קַרְקָעוֹת שֶׁנִּשְׁנֵית בְּעַרְבוֹת מוֹאָב בְּמִשְׁנֵה תוֹרָה, לָמַדְנוּ שֶׁכְּלָלוֹתֶיהָ וּפְרָטוֹתֶיהָ כֻּלָּן נֶאֶמְרוּ מִסִּינַי, וּבָא הַכָּתוּב וְלִמֵּד כָּאן עַל כָּל דִּבּוּר שֶׁנִּדְבַּר לְמֹשֶׁה, שֶׁמִּסִּינַי הָיוּ כֻלָּם, כְּלָלוֹתֵיהֶן וְדִקְדּוּקֵיהֶן, וְחָזְרוּ וְנִשְׁנוּ בְּעַרְבוֹת מוֹאָב:
@2 **שבת לה'.** לְשֵׁם ה', כְּשֵׁם שֶׁנֶּאֱמַר בְּשַׁבַּת בְּרֵאשִׁית (עי' ספרא):
@4 **יהיה לארץ.** לַשָּׂדוֹת וְלַכְּרָמִים:
@4 **לא תזמר.** שֶׁקּוֹצְצִין זְמוֹרוֹתֶיהָ, וְתַרְגּוּמוֹ לָא תִכְסָח, וְדוֹמֶה לוֹ "קוֹצִים כְּסוּחִים" (ישעיהו ל"ג), "שְֹרֻפָה בָאֵשׁ כְּסוּחָה" (תהילים פ'):
@5 **את ספיח קצירך.** אֲפִלּוּ לֹא זְרַעְתָּהּ וְהִיא צָמְחָה מִן הַזֶּרַע שֶׁנָּפַל בָּהּ בְּעֵת הַקָּצִיר וְהוּא קָרוּי סָפִיחַ:
@5 **לא תקצור.** לִהְיוֹת מַחֲזִיק בּוֹ כִּשְׁאָר קָצִיר, אֶלָּא הֶפְקֵר יִהְיֶה לַכֹּל:
@5 **נזירך.** שֶׁהִנְזַרְתָּ וְהִפְרַשְׁתָּ בְנֵי אָדָם מֵהֶם וְלֹא הִפְקַרְתָּם:
@5 **לא תבצר.** אוֹתָם אֵינְךָ בוֹצֵר, אֶלָּא מִן הַמֻּפְקָר:
@6 **והיתה שבת הארץ וגו'.** אַעַ"פִּ שֶׁאֲסַרְתִּים עָלֶיךָ, לֹא בַאֲכִילָה וְלֹא בַּהֲנָאָה אֲסַרְתִּים, אֶלָּא שֶׁלֹּא תִנְהֹג בָהֶם כְּבַעַל הַבַּיִת, אֶלָּא הַכֹּל יִהְיוּ שָׁוִים בָּהּ, אַתָּה וּשְׂכִירְךָ וְתוֹשָׁבְךָ:
@6 **שבת הארץ לכם לאכלה.** מִן הַשָּׁבוּת אַתָּה אוֹכֵל, וְאִי אַתָּה אוֹכֵל מִן הַשָּׁמוּר (ספרא):
@6 **לך ולעבדך ולאמתך.** לְפִי שֶׁנֶאֱמַר וְאָכְלוּ אֶבְיֹנֵי עַמֶּךָ (שמות כ"ג), יָכוֹל יִהְיוּ אֲסוּרִים בַּאֲכִילָה לָעֲשִׁירִים, תַּ"לֹ לְךָ וּלְעַבְדְּךָ וְלַאֲמָתֶךָ, הֲרֵי בְעָלִים וַעֲבָדִים וּשְׁפָחוֹת אֲמוּרִים כָּאן (ספרא):
@6 **ולשכירך ולתושבך.** אַף הַגּוֹיִם (שם):
@7 **ולבהמתך ולחיה.** אִם חַיָּה אוֹכֶלֶת, בְּהֵמָה לֹא כָּל שֶׁכֵּן, שֶׁמְּזוֹנוֹתֶיהָ עָלֶיךָ, מַה תַּ"לֹ וְלִבְהֶמְתְּךָ? מַקִּישׁ בְּהֵמָה לַחַיָּה, כָּל זְמַן שֶׁחַיָּה אוֹכֶלֶת מִן הַשָּׂדֶה, הַאֲכֵל לִבְהֶמְתְּךָ מִן הַבַּיִת, כָּלָה לַחַיָּה מִן הַשָּׂדֶה, כַּלֵּה לִבְהֶמְתְּךָ מִן הַבַּיִת (שם; תענית ו'):
@8 **שבתת שנים.** שְׁמִטּוֹת שָׁנִים, יָכוֹל יַעֲשֶׂה שֶׁבַע שָׁנִים רְצוּפוֹת שְׁמִטָּה וְיַעֲשֶׂה יוֹבֵל אַחֲרֵיהֶם, תַּ"לֹ שֶׁבַע שָׁנִים שֶׁבַע פְּעָמִים, הֱוֵי אוֹמֵר כָּל שְׁמִטָּה וּשְׁמִטָּה בִּזְמַנָּהּ (ספרא):
@8 **והיו לך ימי שבע וגו'.** מַגִּיד לְךָ, שֶׁאַעַ"פִּ שֶׁלֹּא עָשִׂיתָ שְׁמִטּוֹת, עֲשֵׂה יוֹבֵל לְסוֹף מ"ט שָׁנָה; וּפְשׁוּטוֹ שֶׁל מִקְרָא: יַעֲלֶה לְךָ חֶשְׁבּוֹן שְׁנוֹת הַשְּׁמִטּוֹת לְמִסְפַּר מ"ט:
@9 **והעברת.** לְשׁוֹן "וַיַּעֲבִירוּ קוֹל בַּמַּחֲנֶה" (שמות ל"ו), לְשׁוֹן הַכְרָזָה (ראש השנה ל"ד):
@9 **ביום הכפרים.** מִמַּשְׁמָע שֶׁנֶּאֱמַר בְּיוֹם הַכִּפּוּרִים, אֵינִי יוֹדֵעַ שֶׁהוּא בֶּעָשׂוֹר לַחֹדֶשׁ? אִם כֵּן לָמָּה נֶאֱמַר **בעשור לחדש** ? אֶלָּא לוֹמַר לְךָ, תְּקִיעַה בֶּעָשׂוֹר לַחֹדֶשׁ דּוֹחָה שַׁבָּת בְּכָל אַרְצְכֶם, וְאֵין תְּקִיעַת רֹאשׁ הַשָּׁנָה דּוֹחָה שַׁבָּת בְּכָל אַרְצְכֶם אֶלָּא בְּבֵית דִּין בִּלְבָד (ספרא):
@10 **וקדשתם.** בִּכְנִיסָתָהּ מְקַדְּשִׁין אוֹתָהּ בְּבֵית דִּין, וְאוֹמְרִים מְקֻדֶּשֶׁת הַשָּׁנָה (ראש השנה כ"ד):
@10 **וקראתם דרור.** לָעֲבָדִים, בֵּין נִרְצַע בֵּין שֶׁלֹּא כָלוּ לוֹ שֵׁשׁ שָׁנִים מִשֶּׁנִּמְכַּר: אָמַר רַבִּי יְהוּדָה מַהוּ לְשׁוֹן דְּרוֹר? כִּמְדַיַּר בֵּי דַיְרָא וְכוּ' — שֶׁדָּר בְּכָל מָקוֹם שֶׁהוּא רוֹצֶה וְאֵינוֹ בִרְשׁוּת אֲחֵרִים (ספרא; ראש השנה ט'):
@10 **יובל הוא.** שָׁנָה זֹאת מֻבְדֶּלֶת מִשְּׁאָר שָׁנִים בִּנְקִיבַת שֵׁם לָהּ לְבַדָּהּ, וּמַה שְּׁמָהּ? יוֹבֵל שְׁמָהּ, עַל שֵׁם תְּקִיעַת שׁוֹפָר:
@10 **ושבתם איש אל אחזתו.** שֶׁהַשָּׂדוֹת חוֹזְרוֹת לְבַעְלֵיהֶן:
@10 **ואיש אל משפחתו תשבו.** לְרַבּוֹת אֶת הַנִּרְצָע (קידושין ט"ו):
@11 **יובל הוא שנת החמשים שנה.** מַה תַּ"לֹ? לְפִי שֶׁנֶּאֱמַר וְקִדַּשְׁתֶּם וְגוֹ' כִּדְאִיתָא בְּרֹאשׁ הַשָּׁנָה (דף ח') וּבְתֹ"כֹּ:
@11 **את נזריה.** אֶת הָעֲנָבִים הַמְשֻׁמָּרִים, אֲבָל בּוֹצֵר אַתָּה מִן הַמֻּפְקָרִים; כְּשֵׁם שֶׁנֶּאֱמַר בַּשְּׁבִיעִית כָּךְ נֶאֱמַר בַּיּוֹבֵל, נִמְצְאוּ שְׁתֵּי שָׁנִים קְדוֹשׁוֹת סְמוּכוֹת זוֹ לָזוֹ — שְׁנַת מ"ט שְׁמִטָּה, וּשְׁנַת הַחֲמִשִּׁים יוֹבֵל:
@12 **קדש תהיה לכם.** תּוֹפֶסֶת דָּמֶיהָ כְּהֶקְדֵּשׁ, יָכוֹל תֵּצֵא הִיא לְחֻלִּין, תַּ"לֹ **תהיה** — בַּהֲוָיָתָהּ תְּהֵא (ספרא; סוכה מ'):
@12 **מן השדה תאכלו.** עַ"יְ הַשָּׂדֶה אַתָּה אוֹכֵל מִן הַבַּיִת, שֶׁאִם כָּלָה לַחַיָּה מִן הַשָּׂדֶה, אַתָּה צָרִיךְ לְבַעֵר מִן הַבַּיִת; כְּשֵׁם שֶׁנֶּאֱמַר בַּשְּׁבִיעִית כָּךְ נֶאֱמַר בַּיּוֹבֵל (ספרא):
@13 **תשבו איש אל אחזתו.** וַהֲרֵי כְבָר נֶאֱמַר וְשַׁבְתֶּם אִישׁ אֶל אֲחֻזָּתוֹ? אֶלָּא לְרַבּוֹת הַמּוֹכֵר שָׂדֵהוּ וְעָמַד בְּנוֹ וּגְאָלָהּ שֶׁחוֹזֶרֶת לְאָבִיו בַּיּוֹבֵל (שם):
@14 **וכי תמכרו וגו'.** לְפִי פְשׁוּטוֹ כְמַשְׁמָעוֹ; וְעוֹד יֵשׁ דְּרָשָׁה: מִנַּיִן כְּשֶׁאַתָּה מוֹכֵר, מְכֹר לְיִשְׂרָאֵל חֲבֵרְךָ? תַּ"לֹ וְכִי תִמְכְּרוּ מִמְכָּר — לַעֲמִיתְךָ מְכֹר, וּמִנַּיִן שֶׁאִם בָּאתָ לִקְנוֹת קְנֵה מִיִּשְׂרָאֵל חֲבֵרְךָ? תַּ"לֹ אוֹ קָנֹה — מִיַּד עֲמִיתֶךָ (ספרא):
@14 **אל תונו.** זוֹ אוֹנָאַת מָמוֹן (בבא מציעא נ"ח):
@15 **במספר שנים אחר היובל תקנה.** זֶהוּ פְשׁוּטוֹ לְיַשֵּׁב הַמִּקְרָא עַל אָפְנָיו: עַל הָאוֹנָאָה בָּא לְהַזְהִיר, כְּשֶׁתִּמְכֹּר אוֹ תִקְנֶה קַרְקַע, דְּעוּ כַּמָּה שָׁנִים יֵשׁ עַד הַיּוֹבֵל, וּלְפִי הַשָּׁנִים וּתְבוּאוֹת הַשָּׂדֶה שֶׁהִיא רְאוּיָה לַעֲשׂוֹת יִמְכֹּר הַמּוֹכֵר וְיִקְנֶה הַקּוֹנֶה, שֶׁהֲרֵי סוֹפוֹ לְהַחֲזִירָהּ לוֹ בִּשְׁנַת הַיּוֹבֵל, אִם יֵשׁ שָׁנִים מֻעָטוֹת וְזֶה מוֹכְרָהּ בְּדָמִים יְקָרִים, הֲרֵי נִתְאַנָּה לוֹקֵחַ, וְאִם יֵשׁ שָׁנִים מְרֻבּוֹת וְאָכַל מִמֶּנָּה תְּבוּאוֹת הַרְבֵּה, הֲרֵי נִתְאַנָּה מוֹכֵר, לְפִיכָךְ צָרִיךְ לִקְנוֹתָהּ לְפִי הַזְּמַן, וְזֶהוּ שֶׁנֶּאֱמַר בְּמִסְפַּר שְׁנֵי תְבוּאֹת יִמְכָּר לָךְ — לְפִי מִנְיַן שְׁנֵי הַתְּבוּאוֹת שֶׁתְּהֵא עוֹמֶדֶת בְּיַד הַלּוֹקֵחַ תִּמְכֹּר לוֹ. וְרַבּוֹתֵינוּ דָרְשׁוּ מִכָּאן שֶׁהַמּוֹכֵר שָׂדֵהוּ אֵינוֹ רַשַּׁאי לִגְאֹל פָּחוֹת מִשְׁתֵּי שָׁנִים — שֶׁתַּעֲמֹד שְׁתֵּי שָׁנִים בְּיַד הַלּוֹקֵחַ מִיּוֹם לְיוֹם, וַאֲפִלּוּ יֵשׁ שָׁלוֹשׁ תְּבוּאוֹת בְּאוֹתָן שְׁתֵּי שָׁנִים, כְּגוֹן שֶׁמְּכָרָהּ לוֹ בְּקָמוֹתֶיהָ; וּשְׁנֵי אֵינוֹ יוֹצֵא מִפְּשׁוּטוֹ — כְּלוֹמַר מִסְפַּר שָׁנִים שֶׁל תְּבוּאוֹת וְלֹא שֶׁל שִׁדָּפוֹן, וּמִעוּט שָׁנִים שְׁנַיִם (ספרא; ערכין כ"ט):
@16 **תרבה מקנתו.** תִּמְכְּרֶנָּה בְיֹקֶר:
@16 **תמעיט מקנתו.** תַּמְעִיט בְּדָמֶיהָ:
@17 **ולא תונו איש את עמיתו.** כָּאן הִזְהִיר עַל אוֹנָאַת דְּבָרִים, שֶׁלֹּא יַקְנִיט אֶת חֲבֵרוֹ וְלֹא יַשִּׂיאֶנּוּ עֵצָה שֶׁאֵינָהּ הוֹגֶנֶת לוֹ, לְפִי דַּרְכּוֹ וַהֲנָאָתוֹ שֶׁל יוֹעֵץ, וְאִ"תֹּ מִי יוֹדֵעַ אִם נִתְכַּוַּנְתִּי לְרָעָה? לְכָךְ נֶאֱמַר וְיָרֵאתָ מֵּאֱלֹהֶיךָ — הַיּוֹדֵעַ מַחֲשָׁבוֹת הוּא יוֹדֵעַ. כָּל דָּבָר הַמָּסוּר לַלֵּב, שֶׁאֵין מַכִּיר אֶלָּא מִי שֶׁהַמַּחֲשָׁבָה בְלִבּוֹ, נֶאֱמַר בּוֹ וְיָרֵאתָ מֵּאֱלֹהֶיךָ (ספרא; בבא מציעא נ"ח):
@18 **וישבתם על הארץ לבטח.** שֶׁבַּעֲוֹן שְׁמִטָּה יִשְׂרָאֵל גּוֹלִים, שֶׁנֶּאֱמַר "אָז תִּרְצֶה הָאָרֶץ אֶת שַׁבְּתֹתֶיהָ, וְהִרְצָת אֶת שַׁבְּתֹתֶיהָ" (ויקרא כ"ו), וְשִׁבְעִים שָׁנָה שֶׁל גָּלוּת בָּבֶל כְּנֶגֶד שִׁבְעִים שְׁמִטּוֹת שֶׁבִּטְּלוּ הָיוּ:
@19 **ונתנה הארץ וגו', וישבתם לבטח עליה.** שֶׁלֹּא תִדְאֲגוּ מִשְּׁנַת בַּצֹּרֶת:
@19 **ואכלתם לשבע.** אַף בְּתוֹךְ הַמֵּעַיִם תְּהֵא בוֹ בְּרָכָה (עי' ספרא):
@20 **ולא נאסף.** אֶל הַבַּיִת:
@20 **את תבואתנו.** כְּגוֹן יַיִן וּפֵרוֹת הָאִילָן וּסְפִיחִין הַבָּאִים מֵאֵלֵיהֶם:
@21 **לשלש השנים.** לִקְצָת הַשִּׁשִּׁית — מִנִּיסָן וְעַד רֹ"הַ, וְלַשְּׁבִיעִית, וְלַשְּׁמִינִית, שֶׁיִּזְרְעוּ בַשְּׁמִינִית בְּמַרְחֶשְׁוָן וְיִקְצְרוּ בְנִיסָן:
@22 **עד השנה התשיעת.** עַד חַג הַסֻּכּוֹת שֶׁל תְּשִׁיעִית, שֶׁהוּא עֵת בֹּא תְּבוּאָתָהּ שֶׁל שְׁמִינִית לְתוֹךְ הַבַּיִת, שֶׁכָּל יְמוֹת הַקַּיִץ הָיוּ בַשָּׂדֶה בַּגְּרָנוֹת, וּבְתִשְׁרֵי הוּא עֵת הָאָסִיף לַבַּיִת; וּפְעָמִים שֶׁהָיְתָה צְרִיכָה לַעֲשׂוֹת לְאַרְבַּע שָׁנִים — בַּשִּׁשִּׁית שֶׁלִּפְנֵי הַשְּׁמִטָּה הַשְּׁבִיעִית, שֶׁהֵן בְּטֵלִין מֵעֲבוֹדַת קַרְקַע שְׁתֵּי שָׁנִים רְצוּפוֹת — הַשְּׁבִיעִית וְהַיּוֹבֵל, וּמִקְרָא זֶה נֶאֱמַר בִּשְׁאָר הַשְּׁמִטּוֹת כֻּלָּן:
@23 **והארץ לא תמכר.** לִתֵּן לָאו עַל חֲזָרַת שָׂדוֹת לַבְּעָלִים בַּיּוֹבֵל, שֶׁלֹּא יְהֵא הַלּוֹקֵחַ כּוֹבְשָׁהּ:
@23 **לצמתת.** לִפְסִיקָה, לִמְכִירָה פְסוּקָה עוֹלָמִית:
@23 **כי לי הארץ.** אַל תֵּרַע עֵינְךָ בָהּ שֶׁאֵינָהּ שֶׁלְּךָ (ספרא):
@24 **ובכל ארץ אחזתכם.** לְרַבּוֹת בָּתִּים וְעֶבֶד עִבְרִי, וְדָבָר זֶה מְפֹרָשׁ בְּקִדּוּשִׁין בְּפֶרֶק רִאשׁוֹן (דף כ"א). וּלְפִי פְשׁוּטוֹ סָמוּךְ לְפָרָשָׁה שֶׁלְּאַחֲרָיו, שֶׁהַמּוֹכֵר אֲחֻזָּתוֹ רַשָּׁאִי לְגָאֳלָהּ לְאַחַר שְׁתֵּי שָׁנִים, אוֹ הוּא אוֹ קְרוֹבוֹ, וְאֵין הַלּוֹקֵחַ יָכוֹל לְעַכֵּב:
@25 **כי ימוך אחיך ומכר.** מְלַמֵּד שֶׁאֵין אָדָם רַשַּׁאי לִמְכֹּר שָׂדֵהוּ אֶלָּא מֵחֲמַת דֹּחַק עֹנִי (עי' ספרא):
@25 **מאחזתו.** וְלֹא כֻּלָּהּ, לִמֵּד דֶּרֶךְ אֶרֶץ, שֶׁיְּשַׁיֵּר שָׂדֶה לְעַצְמוֹ:
@25 **וגאל את ממכר אחיו.** וְאֵין הַלּוֹקֵחַ יָכוֹל לְעַכֵּב:
@26 **ואיש כי לא יהיה לו גאל.** וְכִי יֵשׁ לְךָ אָדָם בְּיִשְֹרָאֵל שֶׁאֵין לוֹ גּוֹאֲלִים? אֶלָּא גּוֹאֵל שֶׁיּוּכַל לִגְאֹל מִמְכָּרוֹ (קידושין כ"א):
@27 **וחשב את שני ממכרו.** "כַּמָּה שָׁנִים הָיוּ עַד הַיּוֹבֵל? כָּךְ וְכָךְ, וּבְכַמָּה מְכַרְתִּיהָ לְךָ? בְּכָךְ וְכָךְ, עָתִיד הָיִיתָ לְהַחֲזִירָהּ בַּיּוֹבֵל, נִמְצֵאתָ קוֹנֶה מִסְפַּר הַתְּבוּאוֹת כְּפִי חֶשְׁבּוֹן שֶׁל כָּל שָׁנָה, אָכַלְתָּ אוֹתָהּ שָׁלוֹשׁ שָׁנִים אוֹ אַרְבַּע, הוֹצֵא אֶת דְּמֵיהֶן מִן הַחֶשְׁבוֹן וְטֹל אֶת הַשְּׁאָר"; וְזֶהוּ וְהֵשִׁיב אֶת הָעֹדֵף בִּדְמֵי הַמֶּקַח עַל הָאֲכִילָה שֶׁאֲכָלָהּ וְיִתְּנֵם לַלּוֹקֵחַ:
@27 **לאיש אשר מכר לו.** הַמּוֹכֵר הַזֶּה שֶׁבָּא לְגָאֳלָהּ:
@28 **די השיב לו.** מִכָּאן שֶׁאֵינוֹ גוֹאֵל לַחֲצָאִין (ספרא; ערכין ל'):
@28 **עד שנת היובל.** שֶׁלֹּא יִכָּנֵס לְתוֹךְ אוֹתָהּ שָׁנָה כְּלוּם, שֶׁהַיּוֹבֵל מְשַׁמֵּט בִּתְחִלָּתוֹ (ספרא; ערכין כ"ח):
@29 **בית מושב עיר חומה.** בַּיִת בְּתוֹךְ עִיר הַמֻּקֶּפֶת חוֹמָה מִימוֹת יְהוֹשֻׁעַ בִּן נוּן (ספרא):
@29 **והיתה גאלתו.** לְפִי שֶׁנֶּאֱמַר בְּשָׂדֶה שֶׁיָּכוֹל לְגָאֳלָהּ מִשְּׁתֵי שָׁנִים וָאֵילָךְ כָּל זְמַן שֶׁיִּרְצֶה, וּבְתוֹךְ שְׁתֵּי שָׁנִים הָרִאשׁוֹנִים אֵינוֹ יָכוֹל לְגָאֳלָהּ, הֻצְרַךְ לְפָרֵט בָּזֶה שֶׁהוּא חִלּוּף — שֶׁאִם רָצָה לִגְאֹל בְּשָׁנָה רִאשׁוֹנָה גּוֹאֲלָהּ, וּלְאַחַר מִכָּאן אֵינוֹ גוֹאֲלָהּ:
@29 **והיתה גאלתו.** שֶׁל בַּיִת:
@29 **ימים.** יְמֵי שָׁנָה שְׁלֵמָה קְרוּיִים יָמִים, וְכֵן "תֵּשֵׁב הַנַּעֲרָה אִתָּנוּ יָמִים" (בראשית כ"ד):
@30 **וקם הבית … צמיתת.** יָצָא מִכֹּחוֹ שֶׁל מוֹכֵר וְעוֹמֵד בְּכֹחוֹ שֶׁל קוֹנֶה:
@30 **אשר לא חמה.** "לוֹ" קָרֵינָן, אָמְרוּ רַבּוֹתֵינוּ זִ"לִ אַעַ"פִּ שֶׁאֵין לוֹ עַכְשָׁיו הוֹאִיל וְהָיְתָה לוֹ קֹדֶם לָכֵן; וְעִיר נְקֵבָה הִיא, וְהֻצְרַךְ לִכְתֹּב "לָהּ", אֶלָּא מִתּוֹךְ שֶׁצָּרִיךְ לִכְתֹּב "לֹא" בִּפְנִים, תִּקְּנוּ "לוֹ" בַּמָּסֹרֶת — זֶה נוֹפֵל עַל זֶה:
@30 **לא יצא ביבל.** אָמַר רַב סַפְרָא אִם פָּגַע בּוֹ יוֹבֵל בְּתוֹךְ שְׁנָתוֹ לֹא יֵצֵא (עי' ערכין ל"א):
@31 **ובתי החצרים.** כְּתַרְגּוּמוֹ "פַּצְחִין" — עֲיָרוֹת פְּתוּחוֹת מֵאֵין חוֹמָה, וְיֵשׁ הַרְבֵּה בְּסֵפֶר יְהוֹשֻׁעַ, "הֶעָרִים וְחַצְרֵיהֶם" (יהושע י"ג), "בְּחַצְרֵיהֶם וּבְטִירֹתָם" (בראשית כ"ה):
@31 **על שדה הארץ יחשב.** הֲרֵי הֵן כְּשָׂדוֹת, הַנִּגְאָלִים עַד הַיּוֹבֵל וְיוֹצְאִין בַּיּוֹבֵל לַבְּעָלִים אִם לֹא נִגְאֲלוּ:
@31 **גאלה תהיה לו.** מִיָּד, אִם יִרְצֶה, וּבָזֶה יָפֶה כֹחוֹ מִכֹּחַ שָׂדוֹת, שֶׁהַשָּׂדוֹת אֵין נִגְאֲלוֹת עַד שְׁתֵּי שָׁנִים (ערכין ל"ג):
@31 **וביבל יצא.** בְּחִנָּם:
@32 **וערי הלוים.** אַרְבָּעִים וּשְׁמוֹנֶה עִיר שֶׁנִתְּנוּ לָהֶם:
@32 **גאלת עולם.** גּוֹאֵל מִיָּד, אֲפִלּוּ לִפְנֵי שְׁתֵּי שָׁנִים, אִם מָכְרוּ שָׂדֶה מִשְּׂדוֹתֵיהֶם הַנְּתוּנוֹת לָהֶם בְּאַלְפַּיִם אַמָּה סְבִיבוֹת הֶעָרִים, אוֹ אִם מָכְרוּ בַיִת בְּעִיר חוֹמָה, גּוֹאֲלִין לְעוֹלָם וְאֵינוֹ חָלוּט לְסוֹף שָׁנָה (שם):
@33 **ואשר יגאל מן הלוים.** וְאִם יִקְנֶה בַיִת אוֹ עִיר מֵהֶם וְיֵצֵא בַיּוֹבֵל אוֹתוֹ מִמְכָּר שֶׁל בַּיִת אוֹ שֶׁל עִיר וְיָשׁוּב לַלֵּוִי שֶׁמְּכָרוֹ, וְלֹא יִהְיֶה חָלוּט כִּשְׁאָר בָּתֵּי עָרֵי חוֹמָה שֶׁל יִשְׂרָאֵל, וּגְאֻלָּה זוֹ לְשׁוֹן מְכִירָה; דָּ"אַ, לְפִי שֶׁנֶּאֱמַר גְּאֻלַּת עוֹלָם תִּהְיֶה לַלְוִיִּם, יָכוֹל לֹא דִּבֵּר הַכָּתוּב אֶלָּא בְּלוֹקֵחַ יִשְׂרָאֵל שֶׁקָּנָה בַיִת בְּעָרֵי הַלְוִיִּם, אֲבָל לֵוִי שֶׁקָּנָה מִלֵּוִי, יִהְיֶה חָלוּט, תַּ"לֹ וַאֲשֶׁר יִגְאַל מִן הַלְוִיִּם — אַף הַגּוֹאֵל מִיַּד לֵוִי גּוֹאֵל גְּאֻלַּת עוֹלָם:
@33 **ויצא ממכר בית.** הֲרֵי זוֹ מִצְוָה אַחֶרֶת, וְאִם לֹא גְאָלָהּ, יוֹצְאָה בַיּוֹבֵל וְאֵינוֹ נֶחְלָט לְסוֹף שָׁנָה כְּבַיִת שֶׁל יִשְֹרָאֵל:
@33 **כי בתי ערי הלוים הוא אחזתם.** לֹא הָיָה לָהֶם נַחֲלַת שָׂדוֹת וּכְרָמִים, אֶלָּא עָרִים לָשֶׁבֶת וּמִגְרְשֵׁיהֶם, לְפִיכָךְ הֵם לָהֶם בִּמְקוֹם שָׂדוֹת, וְיֵשׁ לָהֶם גְּאֻלָּה כְשָׂדוֹת, כְּדֵי שֶׁלֹּא תֻּפְקַע נַחֲלָתָם מֵהֶם:
@34 **ושדה מגרש עריהם לא ימכר.** מֶכֶר גִּזְבָּר, שֶׁאִם הִקְדִּישׁ בֶּן לֵוִי אֶת שָׂדֵהוּ וְלֹא גְאָלָהּ וּמְכָרָהּ גִּזְבָּר, אֵינָהּ יוֹצְאָה לַכֹּהֲנִים בַּיּוֹבֵל כְּמוֹ שֶׁנֶּאֱמַר בְּיִשְׂרָאֵל וְאִם מָכַר אֶת הַשָּׂדֶה לְאִישׁ אַחֵר לֹא יִגָּאֵל עוֹד (ויקרא כ"ז), אֲבָל בֶּן לֵוִי גּוֹאֵל לְעוֹלָם:
@35 **והחזקת בו.** אַל תַּנִּיחֵהוּ שֶׁיֵּרֵד וְיִפֹּל וְיִהְיֶה קָשֶׁה לַהֲקִימוֹ, אֶלָּא חַזְּקֵהוּ מִשְּׁעַת מוֹטַת הַיָּד; לְמָה זֶה דוֹמֶה? לְמַשּׂאוֹי שֶׁעַל הַחֲמוֹר, עוֹדֵהוּ עַל הַחֲמוֹר אֶחָד תּוֹפֵס בּוֹ וּמַעֲמִידוֹ, נָפַל לָאָרֶץ, חֲמִשָּׁה אֵין מַעֲמִידִין אוֹתוֹ:
@35 **גר ותושב.** אַף אִם הוּא גֵּר אוֹ תוֹשָׁב; וְאֵיזֶהוּ תוֹשָׁב? כָּל שֶׁקִּבֵּל עָלָיו שֶׁלֹּא לַעֲבֹד עֲ"זָ וְאוֹכֵל נְבֵלוֹת (עי' ספרא):
@36 **נשך ותרבית.** חַד שַׁוִּינְהוּ רַבָּנָן, וְלַעֲבֹר עָלָיו בִּשְׁנֵי לָאוִין (בבא מציעא ס'):
@36 **ויראת מאלהיך.** לְפִי שֶׁדַּעְתּוֹ שֶׁל אָדָם נִמְשֶׁכֶת אַחַר הָרִבִּית, וְקָשֶׁה לִפְרֹשׁ הֵימֶנּוּ, וּמוֹרֶה לְעַצְמוֹ הֶתֵּר בִּשְׁבִיל מְעוֹתָיו שֶׁהָיוּ בְטֵלוֹת אֶצְלוֹ, הֻצְרַךְ לוֹמַר וְיָרֵאתָ מֵּאֱלֹהֶיךָ, אוֹ הַתּוֹלֶה מְעוֹתָיו בְּגוֹי כְּדֵי לְהַלְווֹתָם לְיִשְֹרָאֵל בְּרִבִּית, הֲרֵי זֶה דָבָר הַמָּסוּר לְלִבּוֹ שֶׁל אָדָם וּמַחֲשַׁבְתּוֹ, לְכָךְ הֻצְרַךְ לוֹמַר וְיָרֵאתָ מֵּאֱלֹהֶיךָ (שם ס"א):
@38 **אשר הוצאתי וגו'.** וְהִבְחַנְתִּי בֵין בְּכוֹר לְשֶׁאֵינוֹ בְכוֹר, אַף אֲנִי יוֹדֵעַ וְנִפְרָע מִן הַמַּלְוֶה מָעוֹת לְיִשְׂרָאֵל בְּרִבִּית וְאוֹמֵר שֶׁל גּוֹי הֵם; דָּ"אַ: אֲשֶׁר הוֹצֵאתִי אֶתְכֶם מֵאֶרֶץ מִצְרַיִם עַל מְנָת שֶׁתְּקַבְּלוּ עֲלֵיכֶם מִצְוֹתַי, וַאֲפִלּוּ הֵן כְּבֵדוֹת עֲלֵיכֶם:
@38 **לתת לכם את ארץ כנען.** בִּשְׂכַר שֶׁתְּקַבְּלוּ מִצְוֹתַי:
@38 **להיות לכם לאלהים.** שֶׁכָּל הַדָּר בְּאֶרֶץ יִשְׂרָאֵל אֲנִי לוֹ לֵאלֹהִים וְכָל הַיּוֹצֵא מִמֶּנָּה כְּעוֹבֵד עַ"זָ (ספרא; כתובות ק"י):
@39 **עבדת עבד.** עֲבוֹדָה שֶׁל גְּנַאי שֶׁיְּהֵא נִכָּר בָּהּ כְּעֶבֶד, שֶׁלֹּא יוֹלִיךְ כֵּלָיו אַחֲרָיו לְבֵית הַמֶּרְחָץ וְלֹא יַנְעִיל לוֹ מִנְעָלָיו (עי' ספרא):
@40 **כשכיר כתושב.** עֲבוֹדַת קַרְקַע וּמְלֶאכֶת אֻמָּנוּת כִּשְׁאָר שְׂכִירִים הִתְנַהֵג בּוֹ:
@40 **עד שנת היבל.** אִם פָּגַע בּוֹ יוֹבֵל לִפְנֵי שֵׁשׁ שָׁנִים הַיּוֹבֵל מוֹצִיאוֹ:
@41 **הוא ובניו עמו.** אָמַר רַ' שִׁמְעוֹן אִם הוּא נִמְכַּר, בָּנָיו מִי מְכָרָן? אֶלָּא מִכָּאן שֶׁרַבּוֹ חַיָּב בִּמְזוֹנוֹת בָּנָיו (קידושין כ"ב):
@41 **ואל אחזת אבתיו.** אֶל כְּבוֹד אֲבוֹתָיו, וְאֵין לְזַלְזְלוֹ בְּכָךְ (ספרא; מכילתא י"ג):
@41 **אחזת.** חֲזָקַת:
@42 **כי עבדי הם.** שְׁטָרִי קוֹדֵם (ספרא):
@42 **לא ימכרו ממכרת עבד.** בְּהַכְרָזָה — "כָּאן יֵשׁ עֶבֶד לִמְכֹּר" וְלֹא יַעֲמִידֶנּוּ עַל אֶבֶן הַלֶּקַח (ספרא):
@43 **לא תרדה בו בפרך.** מְלָאכָה שֶׁלֹּא לְצֹרֶךְ, כְּדֵי לְעַנּוֹתוֹ, אַל תֹּאמַר לוֹ, הָחֵם לִי אֶת הַכּוֹס הַזֶּה וְהוּא אֵינוֹ צָרִיךְ, עֲדֹר תַּחַת הַגֶּפֶן עַד שֶׁאָבֹא; שֶׁמָּא תֹאמַר אֵין מַכִּיר בַּדָּבָר אִם לְצֹרֶךְ אִם לָאו, וְאוֹמֵר אֲנִי לוֹ שֶׁהוּא לְצֹרֶךְ, הֲרֵי הַדָּבָר הַזֶּה מָסוּר לְלִבּוֹ, לְכָךְ נֶאֱמַר "וְיָרֵאתָ" (שם):
@44 **ועבדך ואמתך אשר יהיו לך.** אִם תֹּאמַר אִם כֵּן בְּמָה אֶשְׁתַּמֵּשׁ? בַּעֲבָדַי אֵינִי מוֹשֵׁל, בָּאֻמּוֹת אֵינִי נוֹחֵל, שֶׁהֲרֵי הִזְהַרְתַּנִי לֹא תְחַיֶּה כָּל נְשָׁמָה, אֶלָּא מִי יְשַׁמְּשֵׁנִי?
@44 **מאת הגוים.** הֵם יִהְיוּ לְךָ לַעֲבָדִים (שם):
@44 **אשר סביבתיכם.** וְלֹא שֶׁבְּתוֹךְ גְּבוּל אַרְצְכֶם, שֶׁהֲרֵי בָהֶם אָמַרְתִּי לֹא תְחַיֶּה כָּל נְשָׁמָה:
@45 **וגם מבני התושבים.** שֶׁבָּאוּ מִסְּבִיבוֹתֵיכֶם לִשָּׂא נָשִׁים בְּאַרְצְכֶם, וְיָלְדוּ לָהֶם, הַבֵּן הוֹלֵךְ אַחַר הָאָב, וְאֵינוֹ בִּכְלַל לֹא תְחַיֶּה, אֶלָּא אַתָּה מֻתָּר לִקְנוֹתוֹ כְּעֶבֶד (קידושין כ"ז):
@45 **מהם תקנו.** אוֹתָם תִּקְנוּ:
@46 **והתנחלתם אתם לבניכם.** הַחֲזִיקוּ בָהֶם לְנַחֲלָה לְצֹרֶךְ בְּנֵיכֶם אַחֲרֵיכֶם; וְלֹא יִתָּכֵן לְפָרֵשׁ הַנְחִילוּם לִבְנֵיכֶם, שֶׁאִם כֵּן הָיָה לוֹ לִכְתֹּב "וְהִנְחַלְתֶּם" אוֹתָם לִבְנֵיכֶם, וְהִתְנַחַלְתֶּם כְּמוֹ וְהִתְחַזַּקְתֶּם:
@46 **איש באחיו.** לְהָבִיא נָשִׂיא בְעַמָּיו וּמֶלֶךְ בִּמְשָׁרְתָיו שֶׁלֹּא לִרְדּוֹת בְּפָרֶךְ:
@47 **יד גר ותושב.** גֵּר וְהוּא תוֹשָׁב, כְּתַרְגּוּמוֹ עָרֵל תוֹתָב, וְסוֹפוֹ מוֹכִיח — וְנִמְכַּר "לְגֵר תּוֹשָׁב":
@47 **וכי תשיג יד גר ותושב עמך.** מִי גָּרַם לוֹ שֶׁיַּעֲשִׁיר? דִּבּוּקוֹ עִמְּךָ.
@47 **ומך אחיך עמו.** מִי גָּרַם לוֹ שֶׁיָּמוּךְ? דִּבּוּקוֹ עִמּוֹ, עַל יְדֵי שֶׁלָּמַד מִמַּעֲשָׂיו:
@47 **משפחת גר.** זֶה הַגּוֹי, כְּשֶׁהוּא אוֹמֵר לְעֵקֶר, זֶה הַנִּמְכָּר לְעֲ"זַ עַצְמָהּ, לִהְיוֹת לָהּ שַׁמָּשׁ, וְלֹא לֶאֱלֹהוּת אֶלָּא לַחֲטֹב עֵצִים וְלִשְׁאֹב מַיִם (ספרא; בבא קמא קי"ג):
@48 **גאלה תהיה לו.** מִיָּד, אַל תַּנִּיחֵהוּ שֶׁיִּטָּמַע:
@50 **עד שנת היבל.** שֶׁהֲרֵי כָל עַצְמוֹ לֹא קְנָאוֹ אֶלָּא לְעָבְדוֹ עַד הַיּוֹבֵל, שֶׁהֲרֵי בַיּוֹבֵל יֵצֵא, כְּמוֹ שֶׁנֶּאֱמַר לְמַטָּה וְיָצָא בִּשְׁנַת הַיֹּבֵל; וּבְגוֹי שֶׁתַּחַת יָדְךָ הַכָּתוּב מְדַבֵּר (ספרא; קידושין ט"ז), וְאַעַפִּ"כֵ לֹא תָבֹא עָלָיו בַּעֲקִיפִין מִפְּנֵי חִלּוּל הַשֵּׁם (בבא קמא קי"ג), אֶלָּא כְּשֶׁבָּא לִגָּאֵל, יְדַקְדֵּק בַּחֶשְׁבּוֹן, לְפִי הַמַּגִּיעַ בְּכָל שָׁנָה וְשָׁנָה יְנַכֶּה לוֹ הַגּוֹי מִן דָּמָיו, אִם הָיוּ עֶשְׂרִים שָׁנָה מִשֶּׁנִמְכַּר עַד הַיּוֹבֵל, וּקְנָאוֹ בְּעֶשְׂרִים מָנֶה, נִמְצָא שֶׁקָּנָה הַגּוֹי עֲבוֹדַת שָׁנָה בְּמָנֶה, וְאִם שָׁהָה זֶה אֶצְלוֹ חָמֵשׁ שָׁנִים, וּבָא לִגָּאֵל, יְנַכֶּה לוֹ חֲמִשָּׁה מָנִים, וְיִתֵּן לוֹ הָעֶבֶד ט"ו מָנִים, וְזֶהוּ **והיה כסף ממכרו במספר שנים** :
@50 **כימי שכיר יהיה עמו** — חֶשְׁבּוֹן הַמַּגִּיעַ לְכָל שָׁנָה וְשָׁנָה יַחֲשֹׁב, כְּאִלּוּ נִשְׂכַּר עִמּוֹ כָּל שָׁנָה בְּמָנֶה, וִינַכֶּה לוֹ:
@51 **אם עוד רבות בשנים.** עַד הַיּוֹבֵל:
@51 **לפיהן.** הַכֹּל כְּמוֹ שֶׁפֵּרַשְׁתִּי:
@53 **לא ירדנו בפרך לעיניך.** כְּלוֹמַר וְאַתָּה רוֹאֶה (ספרא):
@54 **ואם לא יגאל באלה.** בְּאֵלֶּה הוּא נִגְאָל וְאֵינוֹ נִגְאָל בְּשֵׁשׁ (קידושין ט"ו):
@54 **הוא ובניו עמו.** הַגּוֹי חַיָּב בִּמְזוֹנוֹת בָּנָיו:
@55 **כי לי בני ישראל עבדים.** שְׁטָרִי קוֹדֵם:
@55 **אני ה' אלהיכם.** כָּל הַמְשַׁעְבְּדָן מִלְּמַטָּה כְּאִלּוּ מְשַׁעְבְּדוֹ מִלְמַעְלָה (ספרא):
@56 **לא תעשו לכם אלילים.** כְּנֶגֶד זֶה הַנִּמְכָּר לְגוֹי, שֶׁלֹּא יֹאמַר הוֹאִיל וְרַבִּי מְגַלֶּה עֲרָיוֹת, אַף אֲנִי כְּמוֹתוֹ, הוֹאִיל וְרַבִּי עוֹבֵד עָ"זָ, אַף אֲנִי כְּמוֹתוֹ, הוֹאִיל וְרַבִּי מְחַלֵּל שַׁבָּת, אַף אֲנִי כְּמוֹתוֹ, לְכָךְ נֶאֶמְרוּ מִקְרָאוֹת הַלָּלוּ; וְאַף הַפָּרָשִׁיּוֹת הַלָּלוּ נֶאֶמְרוּ עַל הַסֵּדֶר: בַּתְּחִלָּה הִזְהִיר עַל הַשְּׁבִיעִית, וְאִם חָמַד מָמוֹן וְנֶחְשַׁד עַל הַשְּׁבִיעִית, סוֹפוֹ לִמְכֹּר מִטַּלְטְלָיו, לְכָךְ סָמַךְ לָהּ וְכִי תִמְכְּרוּ מִמְכָּר — (מַה כְּתִיב בֵּיהּ? אוֹ קָנֹה מִיַּד עֲמִיתֶךָ — דָּבָר הַנִּקְנֶה מִיָּד לְיָד) — לֹא חָזַר בּוֹ, סוֹף מוֹכֵר אֲחֻזָּתוֹ, לֹא חָזַר בּוֹ, סוֹף מוֹכֵר אֶת בֵּיתוֹ, לֹא חָזַר בּוֹ, סוֹף לֹוֶה בְרִבִּית — כָּל אֵלּוּ הָאַחֲרוֹנוֹת קָשׁוֹת מִן הָרִאשׁוֹנוֹת — לֹא חָזַר בּוֹ, סוֹף מוֹכֵר אֶת עַצְמוֹ, לֹא חָזַר בּוֹ, לֹא דַיּוֹ לְיִשְׂרָאֵל אֶלָּא אֲפִלּוּ לְגוֹי:
@56 **ואבן משכית.** לְשׁוֹן כִּסּוּי, כְּמוֹ "וְשַׂכֹּתִי כַפִּי" (שמות ל"ג), שֶׁמְּכַסִּין הַקַּרְקַע בְּרִצְפַּת אֲבָנִים:
@56 **להשתחות עליה.** אֲפִלּוּ לַשָּׁמַיִם, לְפִי שֶׁהִשְׁתַּחֲוָאָה בְּפִשּׁוּט יָדַיִם וְרַגְלַיִם הִיא וְאָסְרָה תוֹרָה לַעֲשׂוֹת כֵּן חוּץ מִן הַמִּקְדָּשׁ (מגילה כ"ב):
@57 **אני ה'.** נֶאֱמָן לְשַׁלֵּם שָׂכָר:

@1 **וַיְדַבֵּר ה' אֶל מֹשֶׁה בְּהַר סִינַי** מַה עִנְיַן שְׁמִטָּה לְעִנְיַן הַר סִינַי, וַהֲלֹא נֶאֶמְרוּ כָּל הַמִּצְוֹת מִסִּינַי, אֶלָּא מַה שְׁמִטָּה נֶאֶמְרוּ כְּלָלוֹתֶיהָ וּפְרָטֶיהָ וְדִקְדּוּקֶיהָ מִסִּינַי אַף כֻּלָּן נֶאֶמְרוּ כְּלָלוֹתֵיהֶן וּפְרָטֵיהֶן וְדִקְדּוּקֵיהֶן מִסִּינַי, כָּךְ שְׁנוּיָה בְּתוֹרַת כֹּהֲנִים (ריש הפרשה). וְנִרְאֶה לִי שֶׁכָּךְ פֵּרוּשׁוֹ, לְפִי שֶׁלֹּא מָצִינוּ שְׁמִטַּת קַרְקָעוֹת שֶׁנִּשְׁנֵית בְּעַרְבוֹת מוֹאָב לָמַדְנוּ שֶׁכְּלָלוֹתֶיהָ וּפְרָטֶיהָ כֻּלָּן נֶאֶמְרוּ מִסִּינַי, וּבָא הַכָּתוּב וְלִמֵּד כָּאן עַל כָּל דִּבּוּר שֶׁנִּדְבַּר לְמֹשֶׁה בְּסִינַי שֶׁמִּסִּינַי הָיוּ כְּלָלוֹתֵיהֶן וְדִקְדּוּקֵיהֶן וְחָזְרוּ וְנִשְׁנוּ בְּעַרְבוֹת מוֹאָב, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:א'). וְאֵינוֹ נָכוֹן בְּעֵינַי כְּלָל, שֶׁהַרְבֵּה מִצְוֹת כַּשְּׁמִטָּה שֶׁלֹּא נִשְׁנוּ בְּעַרְבוֹת מוֹאָב וְנֵדַע בָּהֶן שֶׁנֶּאֶמְרוּ כְּלָלוֹתֵיהֶן וּפְרָטֵיהֶן מִסִּינַי אוֹ בְּאֹהֶל מוֹעֵד. וְעוֹד מִנַּיִן שֶׁהֻקְשׁוּ שְׁאָר הַדִּבְּרוֹת שֶׁנִּשְׁנוּ בְּעַרְבוֹת מוֹאָב לַשְּׁמִטָּה, וְלֹא הָיוּ כְּלָלוֹתֵיהֶן מִסִּינַי וּפְרָטֵיהֶם בְּעַרְבוֹת מוֹאָב, וְכֵן הָיָה רָאוּי יוֹתֵר לוֹמַר כִּי הַנִּשְׁנוֹת נִשְׁנוּ לְבָאֵר פְּרָטֵיהֶם, כִּי לֹא נֶאֶמְרוּ בְּסִינַי אֶלָּא כְּלָלוֹתֵיהֶן. אֲבָל הַבָּרַיְתָא הַשְּׁנוּיָה בְּתוֹרַת כֹּהֲנִים פֵּרוּשָׁהּ בָּרוּר, שֶׁהַשְּׁמִטָּה נֶאֶמְרוּ כְּלָלוֹתֶיהָ מִסִּינַי, דִּכְתִיב בְּפָרָשַׁת וְאֵלֶּה הַמִּשְׁפָּטִים "וְהַשְּׁבִיעִת תִּשְׁמְטֶנָּה וּנְטַשְׁתָּהּ וְאָכְלוּ אֶבְיֹנֵי עַמֶּךָ" וְגוֹ' (שמות כג יא), וְאֵלּוּ דִּינֵי הַשְּׁמִטָּה בְּדֶרֶךְ כְּלָל, וּבְכָאן חָזַר וְאָמַר כִּי בְּהַר סִינַי עוֹד נֶאֶמְרוּ כָּל פְּרָטֶיהָ, שֶׁהֲרֵי כֻּלָּם נִזְכְּרוּ בַּפָּרָשָׁה הַזֹּאת, וּבְסוֹף הָעִנְיָן (ויקרא כ"ז:ל"ד) כְּתִיב "אֵלֶּה הַמִּצְוֹת אֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה אֶל בְּנֵי יִשְׂרָאֵל בְּהַר סִינָי", לְהַקִּישׁ כָּל הַמִּצְוֹת אֶל הַשְּׁמִטָּה הַנִּזְכֶּרֶת, שֶׁכֻּלָּן הָיוּ כֵּן שֶׁנֶּאֶמְרוּ בִּכְלָל וּפְרָט, וְהַכֹּל מִסִּינַי. וְכֵן שָׁנוּ שָׁם בְּתוֹרַת כֹּהֲנִים (סוף סיפרא), "אֵלֶּה הַמִּצְוֹת", אֵין נָבִיא רַשַּׁאי לְחַדֵּשׁ עוֹד דָּבָר מֵעַתָּה. "אֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה", כְּדַאי הַשָּׁלִיחַ לְשׁוֹלְחוֹ. "אֶת מֹשֶׁה אֶל בְּנֵי יִשְׂרָאֵל", זְכוּת יִשְׂרָאֵל גָּרְמָה. "בְּהַר סִינַי", שֶׁכֻּלָּם נֶאֶמְרוּ מִסִּינַי, עַד כָּאן בְּת"כ. אֲבָל עִנְיַן עַרְבוֹת מוֹאָב, שֶׁנִּצְטַוָּה שָׁם מֹשֶׁה לְבָאֵר הַתּוֹרָה לַבָּנִים. כָּךְ נִרְאֶה לִי וְזֶה כַּפְתּוֹר וָפֶרַח. וְעִנְיַן הַפָּרָשָׁה הַזֹּאת שֶׁנִּכְתַּב בְּכָאן, אָמַר ר"א (אבן עזרא על ויקרא כ"ה:א'), כִּי זֹאת הַבְּרִית הַכְּתוּבָה בְּפָרָשַׁת וְאֵלֶּה הַמִּשְׁפָּטִים (שמות כד ז), וּכְשֶׁקִּבְּלוּ עַל נַפְשָׁם נַעֲשֶׂה וְנִשְׁמָע אָז נִכְרְתָה הַבְּרִית וְאָמַר לָהֶן כָּל הַפָּרָשָׁה הַזֹּאת, וְהִזְכִּירָהּ בַּמָּקוֹם הַזֶּה לְחַבֵּר תְּנָאֵי הָאָרֶץ, כִּי כַּאֲשֶׁר אָמַר עַל הָעֲרָיוֹת כִּי בַּעֲבוּרָם תָּקִיא אוֹתָם הָאָרֶץ (ויקרא י"ח:כ"ח) כֵּן אָמַר בְּפָרָשַׁת אִם בְּחֻקּוֹתַי עַל שַׁבְּתוֹת הָאָרֶץ (ויקרא כ"ו:ל"ד), וְהֻצְרַךְ תְּחִלָּה לְהַזְכִּיר הַשַּׁבָּתוֹת. וּלְפִי דַּעְתִּי כִּי נִכְתְּבָה כָּאן בְּסֵדֶר נָכוֹן, כִּי פֵּרוּשׁ "בְּהַר סִינַי", בַּעֲלוֹתוֹ שָׁם לְקַבֵּל לוּחוֹת שְׁנִיּוֹת. וּבֵאוּר הָעִנְיָן, כִּי בִּתְחִלַּת אַרְבָּעִים יוֹם הָרִאשׁוֹנִים שֶׁל לוּחוֹת הָרִאשׁוֹנוֹת כָּתַב מֹשֶׁה בְּסֵפֶר הַבְּרִית אֵת כָּל דִּבְרֵי ה' וְאֵת כָּל הַמִּשְׁפָּטִים הַנֶּאֱמָרִים שָׁם, וַיִּזְרֹק דַּם הַבְּרִית עַל הָעָם (שמות כד ח), וּכְשֶׁחָטְאוּ בָּעֵגֶל וְנִשְׁתַּבְּרוּ הַלּוּחוֹת כְּאִלּוּ נִתְבַּטְּלָה הַבְּרִית הַהִיא אֵצֶל הקב"ה, וּכְשֶׁנִּתְרַצָּה הקב"ה לְמֹשֶׁה בְּלוּחוֹת שְׁנִיּוֹת צִוָּהוּ בִּבְרִית חֲדָשָׁה, שֶׁנֶּאֱמַר "הִנֵּה אָנֹכִי כֹּרֵת בְּרִית" (שם לד י), וְהֶחְזִיר שָׁם הַמִּצְוֹת הַחֲמוּרוֹת שֶׁנֶּאֶמְרוּ בְּסֵדֶר וְאֵלֶּה הַמִּשְׁפָּטִים בַּבְּרִית הָרִאשׁוֹנָה, וְאָמַר "כְּתָב לְךָ אֶת הַדְּבָרִים הָאֵלֶּה כִּי עַל פִּי הַדְּבָרִים הָאֵלֶּה כָּרַתִּי אִתְּךָ בְּרִית וְאֶת יִשְׂרָאֵל" (שם פסוק כז). וְרָצָה הקב"ה לְהַחְמִיר עֲלֵיהֶם בַּבְּרִית הַזֹּאת הַשֵּׁנִית שֶׁתִּהְיֶה עֲלֵיהֶם בְּאָלוֹת וּבִקְלָלוֹת, וְשֶׁתִּהְיֶה כָּרִאשׁוֹנָה עַל כָּל הַמִּצְוֹת הָרִאשׁוֹנוֹת וְעַל כָּל הַמִּשְׁפָּטִים, כְּמוֹ שֶׁנֶּאֱמַר בַּבְּרִית הָרִאשׁוֹנָה "אֵת כָּל דִּבְרֵי ה' וְאֵת כָּל הַמִּשְׁפָּטִים" (שם כד ג), וּלְפִיכָךְ אָמַר בְּכָאן בְּסוֹף הַתּוֹכֵחוֹת (ויקרא כ"ו:מ"ו) "אֵלֶּה הַחֻקִּים וְהַמִּשְׁפָּטִים וְהַתּוֹרֹת אֲשֶׁר נָתַן ה' בֵּינוֹ וּבֵין בְּנֵי יִשְׂרָאֵל בְּהַר סִינַי בְּיַד מֹשֶׁה", הוּא רוֹמֵז אֶל כָּל הַמִּצְוֹת וְהַמִּשְׁפָּטִים שֶׁנֶּאֶמְרוּ בַּבְּרִית הָרִאשׁוֹנָה בְּסֵדֶר וְאֵלֶּה הַמִּשְׁפָּטִים, שֶׁהָיוּ כֻּלָּן בַּבְּרִית הַזֹּאת. וְהִנֵּה בְּסֵפֶר הַבְּרִית הָרִאשׁוֹן נֶאֶמְרָה הַשְּׁבִיעִית בִּכְלָל כְּמוֹ שֶׁהִזְכַּרְתִּי, שֶׁנֶּאֱמַר "וְהַשְּׁבִיעִית תִּשְׁמְטֶנָּה וּנְטַשְׁתָּהּ" וְכוּ', וְעַתָּה בַּבְּרִית הַזֹּאת הַשֵּׁנִית נֶאֶמְרָה בִּפְרָטֶיהָ וְדִקְדּוּקֶיהָ וָעֳנָשֶׁיהָ. וּבְעֵת הַבְּרִית הָרִאשׁוֹנָה שֶׁהוּא בְּאַרְבָּעִים יוֹם רִאשׁוֹנִים נִצְטַוָּה מֹשֶׁה עַל הַמִּשְׁכָּן, וּכְשֶׁנִּתְרַצָּה לוֹ הקב"ה וְצִוָּהוּ לִכְרוֹת לָהֶם בְּרִית שְׁנִיָּה יָרַד מֹשֶׁה וַיְצַוֵּם אֵת כָּל אֲשֶׁר צִוָּה ה' אֹתוֹ בְּהַר סִינַי (שם לד לד), וְהָיָה מַעֲשֵׂה הַמִּשְׁכָּן מִכְּלָלָם, וְאָז הִקְהִיל מֹשֶׁה אֶת כָּל עֲדַת בְּנֵי יִשְׂרָאֵל וְאָמַר לָהֶם כְּבַתְּחִלָּה "אֵלֶּה הַדְּבָרִים אֲשֶׁר צִוָּה ה' לַעֲשֹׂת אֹתָם" (שמות לה א) בִּמְלֶאכֶת הַמִּשְׁכָּן. וְהִנֵּה קִבְּלוּ הַדָּבָר בְּשִׂמְחָה, וְיָצְאוּ מִלְּפָנָיו מִיָּד, וּבָאוּ כֻּלָּם וְנָתְנוּ הַנְּדָבָה וְעָשׂוּ הַמִּשְׁכָּן וְהִשְׁלִימוּ מְלַאכְתּוֹ, וְכַאֲשֶׁר הוּקַם, מִיָּד "וַיִּקְרָא אֶל מֹשֶׁה וַיְדַבֵּר ה' אֵלָיו מֵאֹהֶל מוֹעֵד" (ויקרא א א), וְצִוָּהוּ בַּקָּרְבָּנוֹת וּבְכָל תּוֹרַת כֹּהֲנִים, וּמֹשֶׁה צִוָּה הַכֹּל אֶל אַהֲרֹן וְאֶל בָּנָיו וְאֶל כָּל בְּנֵי יִשְׂרָאֵל מִיָּד, וְכַאֲשֶׁר הִשְׁלִים אָמַר לָהֶם, עוֹד צִוָּה אוֹתִי הַשֵּׁם בְּהַר סִינַי לְפָרֵשׁ לָכֶם הַשְּׁמִטָּה וְהַיּוֹבֵל וְלִכְרוֹת לָכֶם עַל כָּל הַמִּצְוָה וְהַמִּשְׁפָּטִים בְּרִית חֲדָשָׁה בְּאָלָה וּבִשְׁבוּעָה. וְלֹא הֻצְרַךְ עַתָּה שֶׁיִּזְבַּח זְבָחִים וְיִזְרֹק חֲצִי הַדָּם עַל הָעָם וַחֲצִי הַדָּם עַל הַמִּזְבֵּחַ כַּאֲשֶׁר עָשָׂה בָּרִאשׁוֹנָה, אֲבָל קִבְּלוּ עֲלֵיהֶם הַבְּרִית הָרִאשׁוֹנָה בְּאָלוֹת וּבִקְלָלוֹת אֵלֶּה. וְזֶה טַעַם "אֲשֶׁר נָתַן ה' בֵּינוֹ וּבֵין בְּנֵי יִשְׂרָאֵל בְּהַר סִינַי" (ויקרא כ"ו:מ"ו), כִּי הוּא הַנּוֹתֵן לָהֶם הַבְּרִית הַזֹּאת, כִּי מָחַל לָהֶם עַל פִּי הַתְּנָאִים הָאֵלּוּ כְּמוֹ שֶׁפֵּרַשְׁתִּי בְּסוֹף כִּי תִשָּׂא (שמות לד כז). וְכֵן בְּרִית עַרְבוֹת מוֹאָב כֵּן הָיָה, שֶׁקִּבְּלוּ עֲלֵיהֶם הַתּוֹרָה בָּאָלוֹת וּבַקְּלָלוֹת הָהֵם, וְהִיא הַבְּרִית כְּמוֹ שֶׁנֶּאֱמַר "אֵלֶּה דִּבְרֵי הַבְּרִית אֲשֶׁר צִוָּה ה' אֶת מֹשֶׁה לִכְרֹת אֶת בְּנֵי יִשְׂרָאֵל בְּאֶרֶץ מוֹאָב מִלְּבַד הַבְּרִית אֲשֶׁר כָּרַת אִתָּם בְּחֹרֵב" (דברים כח סט). וֶאֱמֶת אָמְרוּ שֶׁבִּתְנָאֵי הָאָרֶץ הַשְּׁמִטָּה וְהַיּוֹבֵל, כַּאֲשֶׁר יַזְכִּיר בַּתּוֹכָחוֹת (להלן כו לד לה), וְעַל זֶה נִתְחַדְּשׁוּ בַּבְּרִית הַזֹּאת הַשֵּׁנִית:
@2 **שַׁבָּת לַה'** לְשֵׁם ה', כְּשֵׁם שֶׁנֶּאֱמַר בְּשַׁבַּת בְּרֵאשִׁית, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:ב'). וְרַבּוֹתֵינוּ לֹא כָּךְ נִתְכַּוְּנוּ בְּמִדְרָשָׁם, כִּי כָל הַשַּׁבָּתוֹת גַּם הַמּוֹעֲדִים לְשֵׁם ה' הֵן, וְלֹא יֵאָמֵר בְּאֶחָד מֵהֶם "לַה'", אֲבָל אָמַר "יִהְיֶה לָכֶם שַׁבָּתוֹן" (ויקרא כ"ג:כ"ד), וְאָמַר בְּיוֹם הַכִּפּוּרִים "שַׁבַּת שַׁבָּתוֹן הוּא לָכֶם" (שם לב). וּלְשׁוֹן הַבָּרַיְתָא בְּתוֹרַת כֹּהֲנִים (פרק א ב), "שַׁבָּת לַה'", כְּשֵׁם שֶׁנֶּאֱמַר בְּשַׁבַּת בְּרֵאשִׁית כָּךְ נֶאֱמַר בַּשְּׁבִיעִית "שַׁבָּת לַה'". אֲבָל פֵּרוּשׁ "שַׁבָּת לַה' אֱלֹהֶיךָ" הָאָמוּר בְּשַׁבָּת בְּרֵאשִׁית (שמות כ י), כִּי בוֹ שָׁבַת וַיִּנָּפַשׁ וְעַל כֵּן לֹא תַעֲשֶׂה כָל מְלָאכָה, וּלְכָךְ אָמְרוּ כִּי כֵן נֶאֱמַר בַּשְּׁמִטָּה, כִּי הִיא שְׁבִיעִית בַּשָּׁנִים. וְהִנֵּה בְּכָאן עוֹרְרוּ אוֹתָנוּ בְּסוֹד גָּדוֹל מִסּוֹדוֹת הַתּוֹרָה, כְּבָר רָמַז לָנוּ ר"א שֶׁכָּתַב, וְטַעַם "שַׁבָּת לַה'" כְּיוֹם הַשַּׁבָּת, וְסוֹד יְמוֹת עוֹלָם רָמוּז בַּמָּקוֹם הַזֶּה. וְכוֹף אָזְנְךָ לִשְׁמֹעַ מַה שֶׁאֲנִי רַשַּׁאי לְהַשְׁמִיעֲךָ מִמֶּנּוּ בַּלָּשׁוֹן אֲשֶׁר אַשְׁמִיעֲךָ, וְאִם תִּזְכֶּה תִּתְבּוֹנֵן. כְּבָר כָּתַבְתִּי בְּסֵדֶר בְּרֵאשִׁית (בראשית ב ג) כִּי שֵׁשֶׁת יְמֵי בְּרֵאשִׁית הֵם יְמוֹת עוֹלָם וְיוֹם הַשְּׁבִיעִי שַׁבָּת לַה' אֱלֹהֶיךָ (שמות כ ו), כִּי בּוֹ יִהְיֶה שַׁבָּת לַשֵּׁם הַגָּדוֹל, כְּמוֹ שֶׁשָּׁנִינוּ (תמיד פ"ז מ"ד), בַּשְּׁבִיעִי מֶה הָיוּ אוֹמְרִים, "מִזְמוֹר שִׁיר לְיוֹם הַשַּׁבָּת", לֶעָתִיד לָבֹא שֶׁכֻּלָּהּ שַׁבָּת וּמְנוּחָה לְחַיֵּי הָעוֹלָמִים. וְהִנֵּה הַיָּמִים רֶמֶז לַאֲשֶׁר בָּרָא בְּמַעֲשֵׂה בְּרֵאשִׁית, וְהַשָּׁנִים יִרְמְזוּ לַאֲשֶׁר יִהְיֶה בִּבְרִיאַת כָּל יְמֵי עוֹלָם. וְעַל כֵּן הֶחְמִיר הַכָּתוּב בַּשְּׁמִטָּה יוֹתֵר מִכָּל חַיָּבֵי לָאוִין וְחִיֵּב הַגָּלוּת עָלֶיהָ, כְּמוֹ שֶׁהֶחְמִיר בָּעֲרָיוֹת (ויקרא י"ח:כ"ח), שֶׁנֶּאֱמַר "אָז תִּרְצֶה הָאָרֶץ אֶת שַׁבְּתֹתֶיהָ" (ויקרא כ"ו:ל"ד), וְהֶחְזִיר הָעִנְיָן פְּעָמִים רַבּוֹת "כָּל יְמֵי הָשַּׁמָּה תִּשְׁבֹּת" (שם שם לה), וְנֶאֱמַר "וְהָאָרֶץ תֵּעָזֵב מֵהֶם וְתִרֶץ אֶת שַׁבְּתֹתֶיהָ" (שם שם מג), וְכֵן שָׁנִינוּ (אבות פ"ה מ"ט), גָּלוּת בָּאָה עַל עִנּוּי הַדִּין וְעַל עִוּוּת הַדִּין וְעַל שְׁמִטַּת הָאָרֶץ; מִפְּנֵי שֶׁכָּל הַכּוֹפֵר בָּהּ אֵינוֹ מוֹדֶה בְּמַעֲשֵׂה בְּרֵאשִׁית וּבָעוֹלָם הַבָּא. וְכֵן הֶחְמִיר הַנָּבִיא וְגָזַר גָּלוּת עַל שִׁלּוּחַ עֲבָדִים בַּשָּׁנָה הַשְּׁבִיעִית, שֶׁנֶּאֱמַר (ירמיה לד יג יד) "אָנֹכִי כָּרַתִּי בְרִית אֶת אֲבוֹתֵיכֶם וְגוֹ' מִקֵּץ שֶׁבַע שָׁנִים" וְגוֹ', כִּי גַּם בָּעֶבֶד שְׁבִיעִית וְיוֹבֵל כו'. וְהַיּוֹבֵל יִוָּדַע עוֹד מִבְּרֵאשִׁית עַד וַיְכֻלּוּ, כִּי יָשׁוּבוּ בַּיּוֹבֵל הַכֹּל אִישׁ אֶל אֲחֻזָּתוֹ וְאִישׁ אֶל מִשְׁפַּחְתּוֹ, כִּי הוּא מוּסָד מוּסָּד, הַמַּאֲמִין יַחֲרִישׁ. וְזֶהוּ שֶׁנֶּאֱמַר "וְשָׁבְתָה הָאָרֶץ שַׁבָּת" (כאן), "וּקְרָאתֶם דְּרוֹר בָּאָרֶץ" (ויקרא כ"ה:י'), כִּי הִיא אֶרֶץ הַחַיִּים הַנִּרְמֶזֶת בַּפָּסוּק הָרִאשׁוֹן (בראשית א א), שֶׁבָּהּ נֶאֱמַר "וְהָאָרֶץ אֶזְכֹּר" (ויקרא כ"ו:מ"ב), וּכְבָר זָכַרְתִּי זֶה פְּעָמִים. וְשֶׁמָּא לָזֶה רָמְזוּ רַבּוֹתֵינוּ (ר"ה כא) בְּאָמְרָם, חֲמִשִּׁים שַׁעֲרֵי בִּינָה נִבְרְאוּ בָּעוֹלָם וְכֻלָּם נִמְסְרוּ לְמֹשֶׁה חוּץ מֵאֶחָד; כִּי כָל שְׁמִטָּה שַׁעַר בַּיִת אֶחָד, וְהִנֵּה הוֹדִיעוּהוּ כָּל הַהֲוָיָה מִתְּחִלָּה וְעַד סוֹף חוּץ מִן הַיּוֹבֵל קֹדֶשׁ:
@3 **שֵׁשׁ שָׁנִים תִּזְרַע שָׂדֶךָ** דֶּרֶךְ הַכָּתוּב לוֹמַר כֵּן, "שֵׁשֶׁת יָמִים תַּעֲבֹד וְעָשִׂיתָ כָל מְלַאכְתֶּךָ" (שמות כ ט), "שֵׁשֶׁת יָמִים תַּעֲשֶׂה מַעֲשֶׂיךָ וּבַיּוֹם הַשְּׁבִיעִי תִּשְׁבֹּת" (שם כג יב). וְעַל דֶּרֶךְ רַבּוֹתֵינוּ (ירושלמי כלאים פ"ח ה"א), "שֵׁשׁ שָׁנִים תִּזְרַע שָׂדֶךָ" וְלֹא בַּשְּׁבִיעִית, וְהוּא לָאו הַבָּא מִכְּלַל עֲשֵׂה שֶׁהוּא עֲשֵׂה. וְנִמְצָא הַזּוֹרֵעַ בַּשְּׁבִיעִית עוֹבֵר בַּעֲשֵׂה זֶה וּבְלֹא תַּעֲשֶׂה. וּמִדְרַשׁ אַגָּדָה (מכילתא משפטים כ), ר' יִשְׁמָעֵאל אוֹמֵר, כְּשֶׁיִּשְׂרָאֵל עוֹשִׂין רְצוֹנוֹ שֶׁל מָקוֹם עוֹשִׂין שְׁמִטָּה אַחַת בְּשָׁבוּעַ אֶחָד, שֶׁנֶּאֱמַר "שֵׁשׁ שָׁנִים תִּזְרַע", וּכְשֶׁאֵין עוֹשִׂין רְצוֹנוֹ שֶׁל מָקוֹם עוֹשִׂין אַרְבַּע שְׁמִטִּין בְּשָׁבוּעַ אֶחָד, כֵּיצַד, נָרָהּ שָׁנָה וְזוֹרְעָהּ שָׁנָה נָרָהּ שָׁנָה וְזוֹרְעָהּ שָׁנָה, נִמְצְאוּ אַרְבַּע שְׁמִטִּין בְּשָׁבוּעַ אֶחָד:
@5 **אֵת סְפִיחַ קְצִירְךָ** אֲפִלּוּ לֹא זָרַעְתָּ וְהִיא צָמְחָה מִן הַזֶּרַע שֶׁנָּפַל בִּשְׁעַת הַקָּצִיר, וְהוּא קָרוּי סָפִיחַ, **לֹא תִקְצֹר** לִהְיוֹת מַחֲזִיק בּוֹ כִּשְׁאָר קָצִיר אֶלָּא הֶפְקֵר יִהְיֶה לַכֹּל. **נְזִירֶךָ** , שֶׁהִנְזַרְתָּ וְהִפְרַשְׁתָּ אוֹתָם מִבְּנֵי אָדָם וְלֹא הִפְקַרְתָּם, **לֹא תִבְצֹר** אוֹתָם, אֵינְךָ בּוֹצֵר אֶלָּא מִן הַהֶפְקֵר, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:ה'). וְהַכַּוָּנָה לָרַב בָּזֶה שֶׁהוּא סוֹבֵר שֶׁהַשּׁוֹמֵר שָׂדֵהוּ וּפֵרוֹתָיו בַּשְּׁבִיעִית אֵין הַפֵּרוֹת נֶאֱסָרִין. וְכֵן כָּתַב בְּפֵרוּשָׁיו בְּמַסֶּכֶת יְבָמוֹת (קכב ד"ה של עזיקה) וּבְמַסֶּכֶת סֻכָּה (לט ד"ה אבל), וְכֵן הַדָּבָר הַזֶּה בְּדִין הַתּוֹרָה בִּרְאָיוֹת בְּרוּרוֹת. וְזוֹ שֶׁשְּׁנוּיָה בְּתוֹרַת כֹּהֲנִים (פרק א ג), "וְאֶת עִנְּבֵי נְזִירֶךָ לֹא תִבְצֹר" מִן הַשָּׁמוּר בָּאָרֶץ אֵין אַתָּה בּוֹצֵר אֲבָל בּוֹצֵר אַתָּה מִן הַמֻּפְקָר, יְפָרֵשׁ הָרַב לוֹמַר עִנְבֵי נְזִירוּת לֹא תִּבְצֹר אוֹתָם בִּנְזִירוּתָם, אֲבָל תַּפְקִיר הַכֹּל וְתִבְצֹר עִם הָעֲנִיִּים. וְהַנָּכוֹן בְּפֵרוּשׁ הַכָּתוּב, שֶׁ"עִנְּבֵי נְזִירֶךָ" כְּמוֹ "סְפִיחַ קְצִירְךָ", וְ"לֹא תִבְצֹר" כְּמוֹ "לֹא תִקְצֹר", כִּי הָעִנְיָן בְּכָל הַפָּרָשָׁה יִכְפֹּל הַדִּין בִּשְׁנֵיהֶם, יַזְהִיר בַּשָּׂדֶה וְיַזְהִיר בַּכֶּרֶם, "תִּזְרַע שָׂדֶךָ" וְ"תִזְמֹר כַּרְמֶךָ" (ויקרא כ"ה:ג'), "שָׂדְךָ לֹא תִזְרָע וְכַרְמְךָ לֹא תִזְמֹר" (ויקרא כ"ה:ד'), וְכֵן "וְשֵׁשׁ שָׁנִים תִּזְרַע אֶת אַרְצֶךָ וְהַשְּׁבִיעִית תִּשְׁמְטֶנָּה וּנְטַשְׁתָּהּ כֵּן תַּעֲשֶׂה לְכַרְמְךָ" (שמות כג יא). וּפֵרוּשׁ הַכָּתוּב כִּי הַצּוֹמֵחַ מֵאֵלָיו בַּשָּׂדֶה מִבְּלִי חֲרִישָׁה וּזְרִיעָה לְדַעַת, יִקָּרֵא סְפִיחַ קָצִיר, שֶׁהוּא נִסְפָּח אֶל קְצִיר הַשָּׁנָה שֶׁעָבְרָה, מִגִּזְרַת "וְנִסְפְּחוּ עַל בֵּית יַעֲקֹב" (ישעיהו יד א), וְהַגֶּפֶן שֶׁלֹּא עֲבָדוֹ וְלֹא חָפַר וְלֹא זָמַר אוֹתוֹ, יִקָּרֵא "נָזִיר", כִּי הִזִּירוֹ וְהִפְרִישׁוֹ מִמֶּנּוּ כְּאִלּוּ אֵינוֹ שֶׁלּוֹ, מִגִּזְרַת "אֲשֶׁר נָזֹרוּ מֵעָלַי בְּגִלּוּלֵיהֶם" (יחזקאל יד ה) - פֵּרְשׁוּ מִמֶּנִּי, וְכֵן "וְיִנָּזְרוּ מִקָּדְשֵׁי בְּנֵי יִשְׂרָאֵל" (ויקרא כ"ב:ב'). וְאָמַר אוּנְקְלוֹס (תרגום אונקלוס על ויקרא כ"ה:ה') "שִׁבְקָךְ", שֶׁהִנַּחְתָּ אוֹתָם לַשָּׁמִיר וְלַשַּׁיִת. וְיִתָּכֵן כִּי הַמִּנְהָג בְּיִשְׂרָאֵל שֶׁהַכֶּרֶם אֲשֶׁר הוּא בָּתָה, לֹא יִזָּמֵר וְלֹא יֵעָבֵד וְעוֹלֶה שָׁמִיר וָשַׁיִת, יִקְרְאוּ לוֹ "נָזִיר", כְּלוֹמַר שֶׁהוּא כֶּרֶם הַנָּזִיר, מִפְּנֵי שֶׁהַנָּזִיר אָסוּר בְּיַיִן וּבַעֲנָבִים לַחִים וִיבֵשִׁים וְאֵינוֹ עוֹבֵד כַּרְמוֹ, כִּי כֵן יִקְרְאוּ הַשֵּׂעָר הָאָרֹךְ עַל שֵׁם הַנָּזִיר, "גָּזִּי נִזְרֵךְ וְהַשְׁלִיכִי" (ירמיהו ז כט), וְזֶה טַעַם "עִנְּבֵי נְזִירֶךָ". וְהַכְּלָל שֶׁהֵם הַצּוֹמְחִים מִבְּלִי עֲבוֹדַת הַכֶּרֶם. וְהִנֵּה אָמַר הַכָּתוּב כִּי הַסָּפִיחַ הַנּוֹלָד מֵאֵלָיו בַּשָּׂדֶה לֹא יִקְצֹר אוֹתָם, וְהָעֲנָבִים הַצּוֹמְחִים בַּכֶּרֶם מִבְּלִי עֲבוֹדָה לֹא יִבְצֹר אוֹתָן. וּפֵרוּשׁ הַלָּאוִים שֶׁלֹּא תִּקְצֹר אוֹתָן אַתָּה לְבַדְּךָ לְצֹרֶךְ עַצְמְךָ וְלֹא תִּבְצֹר אוֹתָן לְעַצְמְךָ, אֲבָל תִּהְיֶה שְׁנַת שַׁבָּתוֹן לָאָרֶץ מִן הַזְּרִיעָה וְהַזְּמִירָה, וְתִהְיֶה "שַׁבַּת הָאָרֶץ" כָּל אֲשֶׁר תּוֹצִיא בִּשְׁבִיתָתָהּ מִן הַסָּפִיחַ וְהַנָּזִיר, לְכֻלְּכֶם יַחַד לְאָכְלָה, לְךָ וְלַעֲנִיֶּיךָ וְלַחַיָּה וְלַבְּהֵמָה. וְעַכְשָׁו אָשׁוּב לְפָרֵשׁ הַבָּרָיְתוֹת הַשְּׁנוּיוֹת בְּתוֹרַת כֹּהֲנִים בָּעִנְיָן הַזֶּה, לְפִי שֶׁהֵן מַטְעוֹת. שָׁנוּ שָׁם (פרק ד ה) בַּפָּסוּק "הֵן לֹא נִזְרָע וְלֹא נֶאֱסֹף אֶת תְּבוּאָתֵנוּ" (ויקרא כ"ה:כ'), אִם אֵין זוֹרְעִין מַה אוֹסְפִין, אָמַר רַבִּי עֲקִיבָא, מִכָּאן סָמְכוּ לַסְּפִיחִין שֶׁהֵן אֲסוּרִין בַּשְּׁבִיעִית. וְיֶשְׁנָהּ לְזוֹ בַּגְּמָרָא בְּפֶרֶק מָקוֹם שֶׁנָּהֲגוּ (פסחים נא), וְקָתָנֵי בְּתוֹרַת כֹּהֲנִים, וַחֲכָמִים אוֹמְרִים אֵין סְפִיחִים אֲסוּרִין מִדִּבְרֵי תוֹרָה אֶלָּא מִדִּבְרֵי סוֹפְרִים. אִם כֵּן לָמָּה נֶאֱמַר "הֵן לֹא נִזְרָע וְלֹא נֶאֱסֹף", אָמַרְתָּ לָנוּ אַל תִּזְרְעוּ, וּמַה שֶׁאָנוּ אוֹסְפִין וְאֵין מַכְנִיסִין לְקִיּוּם אָמַרְתָּ לָנוּ בַּעֲרוּהוּ, מָה אָנוּ אוֹכְלִין מִן הַבִּעוּר וְאֵילָךְ, עַד כָּאן. הֲרֵי לְדִבְרֵי חֲכָמִים אֵין אִסּוּר הַסְּפִיחִים אֶלָּא מִדִּבְרֵיהֶם, כְּלוֹמַר שֶׁגָּזְרוּ בָּהֶן לְאָסְרָן לְגַמְרֵי מִשּׁוּם חֲשָׁד, שֶׁלֹּא יִזְרְעוּ וְיֹאמְרוּ סְפִיחִים הֵם. וּלְכָךְ אָמְרוּ בַּיְּרוּשַׁלְמִי (ב"ב פ"ה ה"א), אָמַר רַבִּי יַנַּאי, כָּל הַסְּפִיחִים אֲסוּרִין חוּץ מִן הָעוֹלִים בִּשְׂדֵה בּוּר בִּשְׂדֵה נִיר בִּשְׂדֵה כֶּרֶם בִּשְׂדֵה זֶרַע; שְׂדֵה בּוּר - דְּלָא מַשְׁגַּח עָלֶיהָ, שְׂדֵה נִיר - דְּהוּא בָּעֵי מְתַקְּנָה חַקְלֵהּ, שְׂדֵה כֶּרֶם - שֶׁלֹּא לֶאֱסֹר כַּרְמוֹ. שְׂדֵה זֶרַע - שֶׁאֵינוֹ רוֹצֶה בְּקִיּוּמוֹ. וּמִן הַמַּחְלֹקֶת הַזֶּה שָׁנוּ שָׁם בְּתוֹרַת כֹּהֲנִים (פרק א ג), "אֵת סְפִיחַ קְצִירְךָ לֹא תִקְצוֹר", מִכָּאן סָמְכוּ לַסְּפִיחִין שֶׁיִּהְיוּ אֲסוּרִין בַּשְּׁבִיעִית. שָׁנוּ מִשְׁנָתָם כְּדִבְרֵי רַבִּי עֲקִיבָא, דְּ"לֹא תִקְצֹר" כְּלָל, אֲבָל כְּדִבְרֵי חֲכָמִים, שֶׁלֹּא תַּעֲשֶׂה אוֹתָם קָצִיר לְעַצְמְךָ וְלֹא תַּעֲשֶׂה אוֹתָם בָּצִיר לְעַצְמְךָ, אֶלָּא נְהוֹג בָּהֶם מִנְהַג הֶפְקֵר. וְכֵן "לֹא נֶאֱסֹף אֶת תְּבוּאָתֵנוּ" (ויקרא כ"ה:כ'), שֶׁלֹּא נֶאֱסֹף אֶל בָּתֵּינוּ פֵּרוֹת הָאִילָן וְהַסְּפִיחִים, כִּי בְּהַפְקִירָם לָעֲנִיִּים וְלַחַיָּה וְלַבְּהֵמָה וּבְבִעוּר לֹא נוּכַל לִחְיוֹת בָּהֶן. וְהַסְּפִיחִין הָאֵלּוּ הָאֲסוּרִים הֵם הַגְּדֵלִים בִּזְמַן הָאִסּוּר, בַּתְּבוּאָה כָּל שֶׁהֵבִיאָה שְׁלִישׁ בַּשְּׁבִיעִית, וְכֵן הַיְּרָקוֹת כָּל שֶׁצָּמְחוּ בַּשְּׁבִיעִית אֲסוּרִין מִן הַתּוֹרָה לְדִבְרֵי רַבִּי עֲקִיבָא, וּלְדִבְרֵי חֲכָמִים אֲסוּרִין מִדִּבְרֵי סוֹפְרִים, חוּץ מִן הָעוֹלִים בְּאוֹתָן שָׂדוֹת שֶׁהִזְכִּירוּ בַּיְּרוּשַׁלְמִי שֶׁכָּתַבְנוּ לְמַעְלָה. אֲבָל הַיְּרָקוֹת שֶׁצָּמְחוּ בַּשִּׁשִּׁית וְנִלְקְטוּ בַּשְּׁבִיעִית יֵשׁ בָּהֶן מִשּׁוּם קְדֻשַּׁת שְׁבִיעִית לְכָל דִּינֶיהָ, לְהֶפְסֵד וּלְקָרְבָּנוֹת וְלִסְחוֹרָה וּלְבִעוּר, וְאע"פ שֶׁגָּדְלוּ לְגַמְרֵי בַּשִּׁשִּׁית, מִפְּנֵי שֶׁאָנוּ הוֹלְכִים אַחַר לְקִיטָה בְּיָרָק בֵּין לַמַּעֲשֵׂר בֵּין לַשְּׁבִיעִית. אֲבָל אֵין בָּהֶם מִשּׁוּם סְפִיחִים, שֶׁאֵינָם סְפִיחֵי שְׁבִיעִית שֶׁהֲרֵי בַּשִּׁשִּׁית צָמְחוּ. וַאֲפִלּוּ הוֹסִיפוּ בַּשְּׁבִיעִית אֵין בָּהֶם דִּין סְפִיחִים. וּבָהֶם שָׁנִינוּ (שביעית פ"ח מ"ד), הָאוֹמֵר לַפּוֹעֵל הֵילָךְ אִסָּר זֶה וּלְקֹט לִי יָרָק הַיּוֹם וְכוּ'. וְכֵן שָׁנִינוּ (שם פ"ז מ"ג), לֹא יְהֵא לוֹקֵט יְרָקוֹת שֶׁבָּהּ וּמוֹכֵר בַּשּׁוּק אֲבָל לוֹקֵט הוּא וּבְנוֹ מוֹכֵר עַל יָדוֹ. וּתְנַן נָמֵי (שם פ"ט מ"א), הַפֵּיגָם וְהַיַּרְבּוּזִין וְכֻלָּהּ מַתְנִיתִין עַד וְנִקָּחִים מִכָּל אָדָם בַּשְּׁבִיעִית שֶׁאֵין כַּיּוֹצֵא בָהֶם נִשְׁמָר. וְיֵשׁ אוֹמְרִים שֶׁאֵלּוּ הַנִּזְכָּרִים וְכָל כַּיּוֹצֵא בָּזֶה שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לְזָרְעָן, אֲבָל הֵם מֵאֲלֵיהֶן יוֹצְאִים בֶּהָרִים וּבַנְּהָרוֹת - אֵין בָּהֶן אִסּוּר סְפִיחִים כְּלָל אע"פ שֶׁצָּמְחוּ בַּשְּׁבִיעִית, שֶׁלֹּא גָּזְרוּ אֶלָּא בַּנִּזְרָעִים כְּדֵי שֶׁלֹּא יָבֹאוּ לְזָרְעָם, וְכֵן נִרְאֶה זֶה מִן הַגְּמָרָא מִיְּרוּשַׁלְמִי, וְזֶהוּ עִנְיַן הַסְּפִיחִים שֶׁהִזְכִּירוּ חֲכָמִים בְּכָל מָקוֹם. וְכֵן מִן הַתּוֹרָה שֶׁלֹּא יְהֵא אָדָם שׁוֹמֵר שָׂדֵהוּ וְנוֹעֵל בִּפְנֵי עֲנִיִּים בִּשְׁבִיעִית, וַאֲפִלּוּ רוֹצֶה לְהַפְקִיר אוֹתָן בִּשְׁעַת לְקִיטָה, אֶלָּא יְהֵא הַשָּׂדֶה כָּל הַשָּׁנָה מְזֻמָּן וּמֻפְקָר לָעֲנִיִּים. כָּךְ שָׁנוּ בַּמְּכִילְתָּא (משפטים כ יא), "וְאָכְלוּ אֶבְיוֹנֵי עַמֶּךָ" (שמות כג יא), וְכִי מִפְּנֵי מָה אָמְרָה תּוֹרָה, לֹא שֶׁיֹּאכְלוּ אוֹתָהּ עֲנִיִּים, הֲרֵי אֲנִי מַכְנִיסָהּ וּמְחַלְּקָהּ לָעֲנִיִּים, תַּלְמוּד לוֹמַר "וְהַשְּׁבִיעִית תִּשְׁמְטֶנָּה וּנְטַשְׁתָּהּ", מַגִּיד שֶׁהוּא פּוֹרֵץ בָּהּ פְּרָצוֹת, אֶלָּא שֶׁגָּדְרוּ חֲכָמִים מִפְּנֵי תִּקּוּן עוֹלָם. וְהַגָּדֵר שֶׁגָּדְרוּ חֲכָמִים שֶׁלֹּא יִפְרְצוּ פְּרָצוֹת בַּשָּׂדֶה וּבַכֶּרֶם, אֲבָל לֹא שֶׁיְּהֵא הוּא מְשַׁמֵּר שָׂדֵהוּ וּמַכְנִיס הַפֵּרוֹת לַעֲבֹר עַל דִּבְרֵי תוֹרָה. וְלֹא עוֹד אֶלָּא שֶׁגָּזְרוּ שֶׁלֹּא לִקַּח פֵּרוֹת מִן הַמְשֻׁמָּר וְלֹא מִן הֶחָשׁוּד בְּכָךְ, זֶהוּ שֶׁשָּׁנִינוּ (שביעית פ"ט מ"א), וְנִלְקָחִין מִכָּל אָדָם בַּשְּׁבִיעִית שֶׁאֵין כַּיּוֹצֵא בָּהֶן נִשְׁמָר. וְאָמְרוּ בְּמַסֶּכֶת סֻכָּה (סוכה ל"ט), שֶׁאֵין מוֹסְרִים דְּמֵי פֵּרוֹת שְׁבִיעִית לְעַם הָאָרֶץ יוֹתֵר מִמְּזוֹן שָׁלֹשׁ סְעוּדוֹת. בַּמֶּה דְבָרִים אֲמוּרִים, בְּלוֹקֵחַ מִן הַמֻּפְקָר, אֲבָל בְּלוֹקֵחַ מִן הַמְשֻׁמָּר אֲפִלּוּ כַּחֲצִי אִסָּר אָסוּר. וְהַטַּעַם מִפְּנֵי שֶׁהַלּוֹקֵחַ מִן הַמֻּפְקָר, כְּלוֹמַר דְּבָרִים שֶׁדֶּרֶךְ בְּנֵי אָדָם לַהֲבִיאָם מִן הַהֶפְקֵר אוֹ שֶׁיָּדוּעַ שֶׁהֱבִיאָם מִן הַמָּקוֹם הַמֻּפְקָר, בְּהֶתֵּר הוּא לוֹקֵחַ מִמֶּנּוּ, אֶלָּא שֶׁאִם יַרְבֶּה לוֹ בְּדָמִים יוֹתֵר מִסְּעֻדָּתוֹ לְבוֹ בַּיּוֹם חוֹשְׁשִׁין בְּעַם הָאָרֶץ שֶׁמָּא יַעֲשֶׂה בָּהֶן סְחוֹרָה, אֲבָל לוֹקֵחַ דְּבָרִים שֶׁדַּרְכָּן לְהִשָּׁמֵר - אֲפִלּוּ בְּכַחֲצִי אִסָּר חוֹשְׁשִׁין שֶׁמָּא שְׁמָרָן וְאָסוּר לִקַּח מִמֶּנּוּ, הָא בְּלוֹקֵחַ בִּפְרוּטָה וּפָחוֹת מִכַּחֲצִי אִסָּר לֹא גָּזְרוּ, מִפְּנֵי שֶׁדֶּרֶךְ בְּנֵי אָדָם לְלַקְּטָן בְּכָל מָקוֹם וַאֲפִלּוּ בִּשְׁאָר שְׁנֵי שָׁבוּעַ. וְזֶה שֶׁאָמְרוּ (יבמות קכב), גּוֹי שֶׁהָיָה מוֹכֵר פֵּרוֹת בַּשּׁוּק וְאָמַר פֵּרוֹת הַלָּלוּ שֶׁל עָרְלָה הֵם שֶׁל עֲזֵקָה הֵם, לֹא אָמַר כְּלוּם, לֹא נִתְכַּוֵּן זֶה אֶלָּא לְהַשְׁבִּיחַ מִקָּחוֹ. וּפֵרֵשׁ רַשִׁ"י בְּשֵׁם הָרִאשׁוֹנִים, מִפַּרְדֵּס מְעֻזָּק וְגָדֵר לוֹ סָבִיב, וְהִיא שָׁנָה שְׁבִיעִית, וְאִם הָיוּ מַאֲמִינִים לוֹ הָיָה אָסוּר לִקַּח מִמֶּנּוּ בְּעִיר שֶׁרֻבָּהּ יִשְׂרָאֵל, שֶׁמָּא הוּא אָרִיס לְיִשְׂרָאֵל וּמְשַׁמֵּר לוֹ שָׂדֵהוּ, אוֹ חוֹשְׁשִׁין שֶׁמָּא מִשֶּׁל יִשְׂרָאֵל לִקֵּט וּמוֹכֵר, אוֹ שֶׁהַפֵּרוֹת שֶׁל יִשְׂרָאֵל וּמוֹכֵר עַל יָדוֹ, אוֹ שֶׁמָּא אֵין קִנְיָן לְגוֹי בְּאֶרֶץ יִשְׂרָאֵל לְהַפְקִיעַ דִּינֵי הַשְּׁבִיעִית, וְגָזְרוּ עָלָיו כְּיִשְׂרָאֵל. וּמִכָּל מָקוֹם לֹא אָסְרוּ חֲכָמִים פֵּרוֹת הַשָּׂדֶה הַמְשֻׁמָּר לְכָל אָדָם, אֶלָּא שֶׁלֹּא יִקְחוּ אוֹתָם מִן הַמְּשַׁמֵּר. וּלְכָךְ שָׁנוּ בְּתוֹרַת כֹּהֲנִים (פרק א ג), "וְאֶת עִנְּבֵי נְזִירֶךָ לֹא תִבְצֹר", מִן הַשָּׁמוּר בָּאָרֶץ אִי אַתָּה בּוֹצֵר אֲבָל אַתָּה בּוֹצֵר מִן הַמֻּפְקָר. "לֹא תִבְצֹר" - כְּדֶרֶךְ הַבּוֹצְרִים, מִכָּאן אָמְרוּ תְּאֵנִים שֶׁל שְׁבִיעִית אֵין קוֹצְצִין אוֹתָן בַּמֻּקְצֶה וְאֵין דּוֹרְכִין עֲנָבִים בַּגַּת, אֲבָל דּוֹרֵךְ בַּעֲרֵבָה. וּפֵרוּשׁוֹ מִדְּלָא כְּתִיב עִנְבֵי הַנָּזִיר לֹא תִּבְצֹר, וּכְתִיב "נְזִירֶךָ" - לִדְרֹשׁ לֹא תִבְצוֹר אוֹתָם כְּדֶרֶךְ נָזִיר שֶׁלְּךָ, אֲבָל תִּבְצוֹר אוֹתָם עִם הָעֲנִיִּים כְּדֶרֶךְ שֶׁהֵם בּוֹצְרִים, לוֹמַר שֶׁלֹּא יִשְׁמְרֵם לְעַצְמוֹ אֲבָל יִלְקֹט אוֹתָם עִם הָעֲנִיִּים כְּהֶפְקֵר, וְיִנְהֹג בָּהֶם גַּם כֵּן כְּדֶרֶךְ שֶׁהָעֲנִיִּים נוֹהֲגִין לְדָרְכָן בַּעֲרֵבָה. וְקָתָנֵי הָתָם (שם ה), "וְהָיְתָה שַׁבַּת הָאָרֶץ לָכֶם לְאָכְלָה" - מִן הַשָּׁבוּת בָּאָרֶץ אַתָּה אוֹכֵל אֲבָל אִי אַתָּה אוֹכֵל מִן הַשָּׁמוּר; מִכָּאן אָמְרוּ (שביעית ד ב), שָׂדֶה שֶׁנִּטַּיְּבָה, בֵּית שַׁמַּאי אוֹמְרִין אֵין אוֹכְלִין פֵּרוֹתֶיהָ בַּשְּׁבִיעִית, וּבֵית הִלֵּל אוֹמְרִין אוֹכְלִין. כְּלוֹמַר, כֵּיוָן שֶׁאָמְרָה תּוֹרָה שֶׁיְּהֵא הַשָּׁבוּת לָנוּ לְאָכְלָה וְלֹא הַשָּׁמוּר, אָמְרוּ ב"ש שֶׁהַפֵּרוֹת עַצְמָן נֶאֱסָרִין, וּב"ה סוֹבְרִין שֶׁאֵין הַפֵּרוֹת נֶאֱסָרִין, שֶׁלֹּא בָּא הַכָּתוּב אֶלָּא לֶאֱסֹר לָנוּ שֶׁלֹּא נִשְׁמֹר וְיִהְיוּ לָנוּ הַפֵּרוֹת מִן הַשָּׁבוּת. וְכֵן הָעִנְיָן שֶׁאָמְרוּ שֶׁאֵין קוֹצְצִין הַתְּאֵנִים בַּמֻּקְצֶה וְלֹא דּוֹרְכִין הָעֲנָבִים בַּגַּת, גָּדֵר וְאַסְמַכְתָּא מִדִּבְרֵיהֶם, כְּדֵי שֶׁלֹּא יָבוֹאוּ לִידֵי שִׁמּוּר וַאֲסִיפַת הַפֵּרוֹת וְיִגְזְלוּ אוֹתָם מִן הָעֲנִיִּים. וְזֶה הָעִנְיָן הַשָּׁנוּי כָּאן בַּבָּרָיְתוֹת הַלָּלוּ, וְהוּא דֶּרֶךְ טוֹב וּמְחֻוָּר בַּסֻּגְיוֹת שֶׁבִּגְמָרָא בַּבְלִית וִירוּשַׁלְמִית. וְהֶחָכָם הַבָּקִי יַשְׂכִּיל וְיִמְצָא:
@6 **וְהָיְתָה שַׁבַּת הָאָרֶץ לָכֶם לְאָכְלָה** בַּעֲבוּר שֶׁאָמַר (ויקרא כ"ה:ד') "שַׁבַּת שַׁבָּתוֹן יִהְיֶה לָאָרֶץ" אָמַר שֶׁתִּהְיֶה הַשְּׁבִיתָה הַנִּזְכֶּרֶת לָכֶם לְאָכְלָה וְתִחְיוּ בָּהּ כֻּלְּכֶם, אַתָּה וְעַבְדְּךָ וְהַבְּהֵמָה וְהַחַיָּה, שֶׁתִּחְיוּ כֻּלְּכֶם מֵאֲשֶׁר תּוֹצִיא הָאָרֶץ מֵעַצְמָהּ בִּשְׁבִיתָתָהּ, אוֹ שֶׁהַשָּׁנָה תִּקָּרֵא "שַׁבַּת הָאָרֶץ" כַּאֲשֶׁר יִקָּרֵא הַיּוֹם שַׁבַּת ה' וְשַׁבָּת סְתָם, וְהַטַּעַם עַל תְּבוּאַת הַשַּׁבָּת, כִּי הַשַּׁבָּת לֹא תֵּאָכֵל:
@7 **וְלִבְהֶמְתְּךָ וְלַחַיָּה** אִם חַיָּה אוֹכֶלֶת, בְּהֵמָה לֹא כָל שֶׁכֵּן שֶׁמְּזוֹנוֹתֶיהָ עָלֶיךָ, וּמַה תַּלְמוּד לוֹמַר "וְלִבְהֶמְתְּךָ", הִקִּישׁ בְּהֵמָה לְחַיָּה, כָּל זְמַן שֶׁחַיָּה אוֹכֶלֶת מִן הַשָּׂדֶה אַתָּה מַאֲכִיל לִבְהֶמְתֶּךָ מִן הַבַּיִת, כָּלָה לַחַיָּה מִן הַשָּׂדֶה כַּלֵּה לִבְהֶמְתְּךָ מִן הַבַּיִת, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:ז') מִתּוֹרַת כֹּהֲנִים (פרק א ח). וְהַכִּלּוּי הַזֶּה לֹא פֵּרֵשׁ הָרַב מַהוּ, וְעִנְיָנוֹ שֶׁיְּכַלֶּה הַפֵּרוֹת אַחַר זְמַן מִבֵּיתוֹ לְהַפְקִירָן, וְהוּא בִּעוּר שְׁבִיעִית שֶׁהִזְכִּירוּ חֲכָמִים בְּכָל מָקוֹם. וְאֵין הָעִנְיָן שֶׁיִּהְיוּ הַפֵּרוֹת אַחַר זְמַן הַבִּעוּר אֲסוּרִין בַּהֲנָאָה וּבַאֲכִילָה וִיהֵא מְחֻיָּב לְאַבְּדָם. וְלֹא מָנוּ חֲכָמִים בַּמִּשְׁנָה (סוף תמורה) פֵּרוֹת שְׁבִיעִית לֹא מִן הַנִּשְׂרָפִים וְלֹא מִן הַנִּקְבָּרִים, וְאֵינוֹ אֶלָּא שֶׁהוּא צָרִיךְ לְבַעֲרָם מֵרְשׁוּתוֹ וּלְהַפְקִירָם לָעֲנִיִּים וּלְכָל אָדָם, כְּעִנְיַן "בִּעַרְתִּי הַקֹּדֶשׁ מִן הַבַּיִת" (דברים כו יג). וְכֵן שָׁנִינוּ (שביעית פ"ט מ"ח), הָעֲנִיִּים אוֹכְלִין אַחַר הַבִּעוּר אֲבָל לֹא הָעֲשִׁירִים, דִּבְרֵי ר' יְהוּדָה. רַבִּי יוֹסֵי אוֹמֵר, אֶחָד עֲנִיִּים וְאֶחָד עֲשִׁירִים אוֹכְלִין אַחַר הַבִּעוּר. וּפֵרוּשׁ עֲנִיִּים, כָּל שֶׁלָּקְטוּ הַפֵּרוֹת מִשָּׂדוֹת שֶׁל אֲחֵרִים מִן הַהֶפְקֵר, וַעֲשִׁירִים - בַּעֲלֵי הַשָּׂדוֹת עַצְמָן שֶׁלָּקְטוּ אוֹתָן מִן הַשָּׂדוֹת שֶׁלָּהֶם בְּהֶפְקֵרָם, וְרַבִּי יְהוּדָה אֲסָרָן לָהֶם מִדִּבְרֵיהֶם מִפְּנֵי חֲשָׁד, וְרַבִּי יוֹסֵי מַתִּיר וַהֲלָכָה כִּדְבָרָיו. וְשָׁנוּ בַּתּוֹסֶפְתָּא (שביעית פ"ח ה"א-ה"ד), בָּרִאשׁוֹנָה הָיוּ שְׁלוּחֵי בֵּית דִּין מְחַזְּרִין עַל פִּתְחֵי עֲיָרוֹת, כָּל מִי שֶׁמֵּבִיא פֵּרוֹת לְתוֹךְ יָדוֹ הָיוּ נוֹטְלִין אוֹתָן מִמֶּנּוּ, וְנוֹתְנִין לוֹ מְזוֹן שָׁלֹשׁ סְעוּדוֹת וְהַשְּׁאָר מַכְנִיסִין אוֹתוֹ לְאוֹצָר שֶׁבָּעִיר. הִגִּיעַ זְמַן תְּאֵנִים, שְׁלוּחֵי ב"ד שׂוֹכְרִין פּוֹעֲלִים וְעוֹדְרִים אוֹתָן וְעוֹשִׂים אוֹתָם דְּבֵלָה וְכוּ'. הִגִּיעַ זְמַן זֵיתִים, שְׁלוּחֵי ב"ד שׂוֹכְרִין פּוֹעֲלִים וּמוֹסְקִין אוֹתָן וְעוֹטְנִין אוֹתָן בְּבֵית הַבַּד וְכוֹנְסִין אוֹתָן בְּחָבִיּוֹת וּמַכְנִיסִין אוֹתָם בָּאוֹצָר שֶׁבָּעִיר. הִגִּיעַ זְמַן עֲנָבִים, שְׁלוּחֵי ב"ד שׂוֹכְרִים פּוֹעֲלִים וּבוֹצְרִים אוֹתָם וְדוֹרְכִים אוֹתָם בַּגַּת וְכוֹנְסִים אוֹתָם בְּחָבִיּוֹת וּמַכְנִיסִין אוֹתָם בָּאוֹצָר שֶׁבָּעִיר, וּמְחַלֵּק לָהֶן מֵהֶן בְּעַרְבֵי שַׁבָּתוֹת כָּל אֶחָד וְאֶחָד לְפִי בֵּיתוֹ. הִגִּיעַ שְׁעַת הַבִּעוּר, עֲנִיִּים אוֹכְלִין אַחַר הַבִּעוּר אֲבָל לֹא עֲשִׁירִים, דִּבְרֵי ר' יְהוּדָה. ר' יוֹסֵי אוֹמֵר, אֶחָד עֲנִיִּים וְאֶחָד עֲשִׁירִים אוֹכְלִין אַחַר הַבִּעוּר. ר' שִׁמְעוֹן אוֹמֵר, עֲשִׁירִים אוֹכְלִין מִן הָאוֹצָר אַחַר הַבִּעוּר. מִי שֶׁיֵּשׁ לוֹ פֵּרוֹת שְׁבִיעִית וְהִגִּיעַ שְׁעַת הַבִּעוּר, מְחַלֵּק מֵהֶן לִשְׁכֵנָיו וְלִקְרוֹבָיו וְלִמְיֻדָּעָיו, וּמוֹצִיא וּמַנִּיחַ עַל פֶּתַח בֵּיתוֹ וְאוֹמֵר, אַחֵינוּ בֵּית יִשְׂרָאֵל כָּל מִי שֶׁצָּרִיךְ לִטֹּל יָבֹא וְיִטֹּל, וְחוֹזֵר וּמַכְנִיס לְתוֹךְ בֵּיתוֹ, וְאוֹכֵל וְהוֹלֵךְ עַד שָׁעָה שֶׁיִּכְלוּ. כָּל זֶה שָׁנוּי בַּתּוֹסֶפְתָּא. וְלָמַדְנוּ מְפֹרָשׁ שֶׁאֵין בִּעוּר אֶלָּא לְבַעֵר הַפֵּרוֹת מֵרְשׁוּתוֹ וּלְהַפְקִירָם. וְעָשׂוּ לָהֶם תַּקָּנוֹת מִדִּבְרֵיהֶם, בָּרִאשׁוֹנָה הָיוּ בֵּית דִּין עוֹשִׂין אוֹצָר בְּכָל עִיר וְעִיר, מִתְּחִלַּת יְצִיאַת הַפֵּרוֹת הָיוּ נוֹטְלִין אוֹתָם מִיַּד מְבִיאֵיהֶן וּמַכְנִיסִין אוֹתָן לְאוֹצָר, וּכְשֶׁיָּבֹא זְמַן לְקִיטַת כָּל אוֹתוֹ הַמִּין, כְּגוֹן שֶׁבָּא זְמַן קָצִיר וְעֵת הַבָּצִיר הִגִּיעַ, ב"ד שׂוֹכְרִים פּוֹעֲלִים וּבוֹצְרִין וּמוֹסְקִין וְלוֹקְטִים כָּל אוֹתוֹ הַמִּין, וְדוֹרְכִים וּמוֹסְקִין בַּגַּת וּבְבֵית הַבַּד כְּדֶרֶךְ שְׁאָר הַשָּׁנִים, וְנוֹתְנִים לָאוֹצָר שֶׁלָּהֶן. וְאֵלּוּ הַפֵּרוֹת הַמְכֻנָּסִים לְאוֹצַר בֵּית דִּין אֵינָן צְרִיכִין בִּעוּר אַחַר שֶׁכְּבָר מְבֹעָרִין הֵם מִן הַבַּיִת. וְאֶחָד עֲנִיִּים וְאֶחָד עֲשִׁירִים מֻתָּרִין לְאַחַר הַבִּעוּר לְקַבֵּל מֵהֶם מִיַּד ב"ד וּלְאָכְלָן. וְכָל זוֹ הַתַּקָּנָה וְהַטֹּרַח שֶׁל ב"ד מִפְּנֵי חֲשָׁד, שֶׁלֹּא יָבֹאוּ לְעַכְּבָם אוֹ לַעֲשׂוֹת מֵהֶם סְחוֹרָה. וּכְשֶׁאֵין אוֹצָר בָּעִיר וְלֹא בֵּית דִּין, וְהַפֵּרוֹת בְּיַד הַמְלַקֵּט אוֹתָם מִן הַהֶפְקֵר, הוּא צָרִיךְ לְבַעֲרָם מִן הַבַּיִת בִּשְׁעַת הַבִּעוּר, וּמַפְקִירָם עַל פֶּתַח בֵּיתוֹ, וְאוֹכְלִין וְהוֹלְכִין לְעוֹלָם. וְזוֹ הִיא שְׁבִיעִית שֶׁאוֹסֶרֶת בְּמִינָהּ בְּמַשֶּׁהוּ (שביעית ז ז) לְבִעוּר, כְּמוֹ שֶׁמֻּזְכָּר בְּמַסֶּכֶת נְדָרִים (נדרים נ"ח), מִפְּנֵי שֶׁיֵּשׁ לָהּ הֶתֵּר בְּבִעוּר מִבֵּיתוֹ. וּמָצָאתִי לְשׁוֹן רַשִׁ"י שֶׁכָּתַב בְּמַסֶּכֶת פְּסָחִים (נב ד"ה משום), וְזֶהוּ בִּעוּרָם, שֶׁמַּפְקִירָם בִּמְקוֹם דְּרִיסַת רַגְלֵי אָדָם וּבְהֵמָה. אוּלַי חָשַׁב הָרַב שֶׁצָּרִיךְ שֶׁיְּהֵא מַפְקִירָם גַּם לַחַיָּה וְלַבְּהֵמָה, לְקַיֵּם בָּהֶם "וְאָכְלוּ אֶבְיוֹנֵי עַמֶּךָ" (שמות כג יא) "וְלִבְהֶמְתְּךָ וְלַחַיָּה אֲשֶׁר בְּאַרְצֶךָ" (כאן), וְהִפְלִיג. וּמִכָּל מָקוֹם אֵינָן נֶאֱסָרִין בַּאֲכִילָה כְּלָל. וּכְבָר שָׁנוּ בַּתּוֹסֶפְתָּא (שביעית פ"ז ה"ג) שֶׁבִּעוּר שְׁבִיעִית כְּבִעוּר מַעֲשֵׂר שֵׁנִי, לֹא שֶׁיְּהֵא בָּהֶם חִלּוּק בְּאִסּוּר אֲכִילָה. וְהָרַב רַבִּי מֹשֶׁה (הל' שמיטה ויובל פ"ז ה"ג) וְהַרְבֵּה מִן הַחֲכָמִים סְבוּרִין שֶׁהַבִּעוּר אוֹסֵר לְגַמְרֵי, וּטְעוּנִין שְׂרֵפָה אוֹ מְפַזֵּר וְזוֹרֶה לָרוּחַ אוֹ מֵטִיל לַיָּם, וְאֵינוֹ כֵּן, כְּמוֹ שֶׁנִּתְבָּאֵר. אֲבָל אִם עִכְּבָם בְּבֵיתוֹ אַחַר הַבִּעוּר כְּדֵי לְאָכְלָן, אֲסוּרִין הֵם בַּאֲכִילָה לְגַמְרֵי. וְזוֹ הִיא שְׁבִיעִית שֶׁאוֹסֶרֶת בְּנוֹתֵן טַעַם לְאַחַר הַבִּעוּר (שביעית ז ז), שֶׁאֵין לָהּ מַתִּירִין. וְאֶפְשָׁר שֶׁהָאִסּוּר הַזֶּה מִדִּבְרֵיהֶם הוּא. וְאוּלַי אֲפִלּוּ הַבִּעוּר כֻּלּוֹ חֹמֶר מִדִּבְרֵי סוֹפְרִים, וְהַבָּרָיְתוֹת הַשְּׁנוּיוֹת בְּתוֹרַת כֹּהֲנִים בְּעִנְיַן הַבִּעוּר אַסְמַכְתָּא מִדְּרַבָּנָן. וְעַל דֶּרֶךְ זוֹ תִּתְפָּרֵשׁ יָפֶה מִשְׁנַת הַכּוֹבֵשׁ שְׁלֹשָׁה כְּבָשִׁים בְּחָבִית אַחַת וְכוּ' (שביעית פ"ט מ"ה), וְכֵן מִשְׁנַת שָׁלֹשׁ אֲרָצוֹת לַשְּׁבִיעִית (שם פ"ו מ"א), דְּקָתָנֵי כָּל שֶׁהֶחֱזִיקוּ עוֹלֵי בָּבֶל מֵאֶרֶץ יִשְׂרָאֵל עַד כְּזִיב לֹא נֶאֱכָל וְלֹא נֶעֱבָד; כָּל שֶׁהֶחֱזִיקוּ עוֹלֵי מִצְרַיִם מִכְּזִיב וְעַד הַנָּהָר וְעַד אֲמָנָה נֶאֱכָל אֲבָל לֹא נֶעֱבָד. הֵקֵלּוּ בַּאֲכִילָה לְאַחַר הַבִּעוּר יוֹתֵר מִן הָעֲבוֹדָה. וְהֻזְכַּר בַּיְּרוּשַׁלְמִי (שביעית סוף פ"ט), חַד בַּר נַשׁ הֲוָה חֲשִׁיד עַל שְׁמִטְּתָא, אֲמַר לְאִתְּתֵהּ, אַפְּקִין חַלְּתָא. אָמְרָה לֵיהּ, הַהוּא גַּבְרָא חֲשִׁיד עַל שְׁמִטְּתָא וְאָמַרְתָּ אַפְּקִין חַלְּתָא. אֲמַר לַהּ, חַלָּה דְּבַר תּוֹרָה, שְׁבִיעִית מִדְּרַבָּן גַּמְלִיאֵל וַחֲבֵרָיו. אוֹתוֹ רֵיקָה הָיָה חָשׁוּד לְעַכֵּב פֵּרוֹת שְׁבִיעִית וּלְאָכְלָן אַחַר הַבִּעוּר, וְאָמַר שֶׁאִסּוּר אֲכִילַת הַטֶּבֶל מִן הַתּוֹרָה, וְהַבִּעוּר וְאִסּוּר אֲכִילַת פֵּרוֹת שְׁבִיעִית אַחַר הַבִּעוּר מִן ר"ג וַחֲבֵרָיו, אוֹ שֶׁהַבִּעוּר מִן הַתּוֹרָה וְאִסּוּר הָאֲכִילָה מִדִּבְרֵיהֶם, וְלֹא הָיָה חוֹשֵׁשׁ אֶלָּא שֶׁלֹּא יֹאכַל אִסּוּרֵי תּוֹרָה. וְכֵיוָן שֶׁהִזְכִּירוּ חֲכָמִים דְּבָרָיו נִרְאֶה שֶׁהֵם אֱמֶת. אוֹ שֶׁמָּא אוֹתוֹ רָשָׁע סָבַר כְּדִבְרֵי רַבִּי שִׁמְעוֹן דַּאֲמַר (מו"ק ב), בִּשְׁתֵּי שְׁמִיטוֹת הַכָּתוּב מְדַבֵּר, וּשְׁבִיעִית בַּזְּמַן הַזֶּה דְּרַבָּנָן אע"פ שֶׁחַלָּה דְּאוֹרָיְתָא:
@9 **בְּיוֹם הַכִּפּוּרִים** מִמַּשְׁמַע שֶׁנֶּאֱמַר "בְּיוֹם הַכִּפּוּרִים" אֵינִי יוֹדֵעַ שֶׁהוּא בֶּעָשׂוֹר לַחֹדֶשׁ, אִם כֵּן לָמָּה נֶאֱמַר "בֶּעָשׂוֹר לַחֹדֶשׁ", אֶלָּא תְּקִיעַת בֶּעָשׂוֹר לַחֹדֶשׁ דּוֹחָה שַׁבָּת בְּכָל אַרְצְכֶם וְאֵין תְּרוּעַת רֹאשׁ הַשָּׁנָה דּוֹחָה שַׁבָּת בְּכָל אַרְצְכֶם אֶלָּא בְּבֵית דִּין בִּלְבַד, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:ט'). וְהִנֵּה הָרַב מִפְּנֵי בְּקִיאוּתוֹ בַּתַּלְמוּד וְהַכֹּל לְפָנָיו כְּשֻׁלְחָן עָרוּךְ, אֵינוֹ חוֹשֵׁשׁ וְסוֹתֵם הַבָּרָיְתוֹת, וְהֵן מַטְעוֹת לִשְׁאָר בְּנֵי אָדָם, שֶׁיָּדוּעַ הוּא וּבָרוּר בַּגְּמָרָא (ר"ה כט) כִּי הַתְּקִיעוֹת כֻּלָּן שֶׁל רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים וַאֲפִלּוּ שֶׁל רְשׁוּת מֻתָּרוֹת הֵן בְּשַׁבָּת, לְפִי שֶׁהִיא חָכְמָה וְאֵינָהּ מְלָאכָה, וְתוֹקְעִין הָיוּ בְּדִין תּוֹרָה בְּשַׁבָּת שֶׁל רֹאשׁ הַשָּׁנָה וְשֶׁל יוֹם הַכִּפּוּרִים בְּכָל מָקוֹם. וְעִנְיַן הַתְּקִיעָה בְּבֵית דִּין תַּקָּנַת רַבָּן יוֹחָנָן בֶּן זַכַּאי הִיא מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ, לְפִי שֶׁגָּזְרוּ בָּהּ מִפְּנֵי שֶׁהַכֹּל חַיָּבִין בִּתְקִיעַת שׁוֹפָר וְאֵין הַכֹּל בְּקִיאִין בִּתְקִיעַת שׁוֹפָר, שֶׁמָּא יִטְּלֶנּוּ בְּיָדוֹ וְיֵלֵךְ אֵצֶל בָּקִי לִלְמֹד וְיַעֲבִירֶנּוּ אַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים, וְהִתִּיר לָנוּ רַבָּן יוֹחָנָן בֶּן זַכַּאי בְּבֵית דִּין בִּלְבַד, וְאֵין לָזֶה עִקָּר בְּעִנְיַן הַכָּתוּב כְּלָל. וּמַה שֶׁהִזְכִּירוּ (בת"כ פרשה ב ה) תְּקִיעָה בֶּעָשׂוֹר דּוֹחָה שַׁבָּת, לוֹמַר שֶׁהִיא נַעֲשֵׂית בְּכָל יוֹם הַכִּפּוּרִים, כִּי הַדְּחִיָּה בְּיוֹם הַכִּפּוּרִים שֶׁחָל לִהְיוֹת בְּשַׁבָּת וְשֶׁחָל לִהְיוֹת בְּחוֹל אַחַת הִיא, שֶׁיּוֹם הַכִּפּוּרִים כְּשַׁבָּת לְכָל מְלָאכָה, בֵּין לְהוֹצָאָה בֵּין לְכָל הַמְּלָאכוֹת. וּמִכָּל מָקוֹם רָצָה הָרַב לְלַמְּדֵנוּ שֶׁתְּקִיעַת שׁוֹפָר בְּיוֹם הַכִּפּוּרִים נַעֲשֵׂית בְּכָל מָקוֹם, שֶׁפֵּרוּשׁ "תַּעֲבִירוּ שׁוֹפָר בְּכָל אַרְצְכֶם" לְלַמֵּד שֶׁכָּל יָחִיד חַיָּב לִתְקֹעַ, וְאֵין הַתְּקִיעָה בְּבֵית דִּין בִּלְבַד כְּמוֹ הַסְּפִירָה:
@10 **יוֹבֵל הִיא** שָׁנָה זוֹ נִבְדֶּלֶת מִשְּׁאָר הַשָּׁנִים בִּנְקִיבַת שֵׁם לְבַדָּהּ, וּמַה שְׁמָהּ, יוֹבֵל שְׁמָהּ, עַל שֵׁם תְּקִיעַת שׁוֹפָר, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:י'). וְכֵן דַּעַת הַמְפָרְשִׁים, מִלְּשׁוֹן "בִּמְשֹׁךְ הַיּוֹבֵל" (שמות יט יג), "שׁוֹפְרוֹת הַיּוֹבְלִים" (יהושע ו ד). וְאֵינוֹ מְחֻוָּר לִי, בַּעֲבוּר "תִּהְיֶה לָכֶם", כִּי מָה טַעַם שֶׁיֹּאמַר בַּשָּׁנָה "תְּקִיעָה הִיא תִּהְיֶה לָכֶם וְשַׁבְתֶּם". וְאוּלַי יֹאמַר הַכָּתוּב "יוֹבֵל הִיא", נְקוּבָה בַּשֵּׁם הַזֶּה שֶׁקָּרָאתִי לָהּ, וְ"תִהְיֶה לָכֶם" לְכֻלְּכֶם, יְדוּעָה בַּתְּקִיעָה שֶׁתִּתְקְעוּ בָּהּ לְהַזְכִּיר עִנְיָנָהּ, שֶׁתָּשׁוּבוּ בָּהּ אִישׁ אֶל אֲחֻזָּתוֹ וְאִישׁ אֶל מִשְׁפַּחְתּוֹ. וְכֵן "יוֹבֵל הִיא שְׁנַת הַחֲמִשִּׁים שָׁנָה תִּהְיֶה לָכֶם", שֶׁתִּהְיֶה לָכֶם יוֹבֵל שֶׁלֹּא תִּזְרְעוּ וְלֹא תִּקְצְרוּ, כְּלוֹמַר יְדוּעָה בְּשֵׁם לִהְיוֹת בָּהּ כָּכָה. וְכָל זֶה אֵינֶנּוּ נָכוֹן בְּעֵינַי, כִּי פֵּרוּשׁ "שׁוֹפְרוֹת הַיּוֹבְלִים" - קַרְנֵי הָאֵלִים, וְגַם תַּרְגּוּם יוֹנָתָן "שׁוֹפָרָא דְּקֶרֶן דִּכְרָא", וְכֵן בַּגְּמָרָא (ר"ה כו), מֵאֵי מַשְׁמַע דְּהַאי יוֹבֵלָא לִשָּׁנָא דְּדִכְרָא הוּא, שֶׁכֵּן בְּעַרְבִי קוֹרִין לְדִכְרָא - יוֹבֵלָא. וְהַשּׁוֹפָר בְּיוֹם הַכִּפּוּרִים אֵין מְיֻחָד לִהְיוֹתוֹ מֵהָאַיִל, אֲבָל כָּל הַשּׁוֹפָרוֹת כְּשֵׁרִין בּוֹ. וְעַל דַּעַת מִשְׁנָתֵנוּ (שם כו) וְכָל הַתַּנָּאִין מִצְוָתוֹ בְּשֶׁל יְעֵלִים, אִם כֵּן לָמָּה תִּקָּרֵא הַשָּׁנָה שְׁנַת הָאַיִל. וְר"א אָמַר כִּי יוֹבֵל כְּטַעַם שִׁלּוּחַ. וּלְפִי דַּעְתִּי לֹא קְרָאוֹ הַכָּתוּב יוֹבֵל עַל הַתְּקִיעָה, רַק עַל הַדְּרוֹר, כִּי לֹא הִזְכִּיר הַשֵּׁם הַזֶּה בַּכָּתוּב הָרִאשׁוֹן שֶׁאָמַר "וְהַעֲבַרְתָּ שׁוֹפַר תְּרוּעָה", אֲבָל אָמַר "וּקְרָאתֶם דְּרוֹר בָּאָרֶץ לְכָל יֹשְׁבֶיהָ", שֶׁיִּהְיוּ כֻּלָּם בְּנֵי חוֹרִין לָדוּר בְּכָל מָקוֹם שֶׁיִּרְצוּ. וְאָמַר "יוֹבֵל הִיא", שֶׁבָּהּ יוּבַל כָּל אִישׁ אֶל אֲחֻזָּתוֹ וְאֶל מִשְׁפַּחְתּוֹ יוֹבִילוּהוּ רַגְלָיו מֵרָחוֹק לָגוּר (ישעיהו כג ז). וְנִשְׁתַּמְּשׁוּ בַּלָּשׁוֹן הַזֶּה בְּעִנְיָנִים רַבִּים, "יוּבַל שַׁי לַה' צְבָאוֹת" (ישעיהו יח ז), וְאָמַר "וְעַל יוּבַל יְשַׁלַּח שָׁרָשָׁיו" (ירמיהו יז ח), "פְּלָגִים יִבְלֵי מָיִם" (ישעיהו ל כה), הֵם הַמַּעֲמַקִּים שֶׁשָּׁם יוּבְלוּ הַמַּיִם, "וְנָתְנָה הָאָרֶץ יְבוּלָהּ" (ויקרא כ"ו:ד'), "וְאֵין יְבוּל בַּגְּפָנִים" (חבקוק ג יז), עִנְיַן הֲבָאָה גַּם כֵּן, כְּמוֹ שֶׁיִּקָּרֵא תְּבוּאָה. וְכֵן בַּאֲרָמִית "וְהוֹלֵךְ מְהֵרָה" (במדבר יז יא) תַּרְגּוּמוֹ "וְאוֹבֵל בִּפְרִיע". וְיִהְיֶה פֵּרוּשׁ "יוֹבֵל הִיא תִּהְיֶה לָכֶם" הֲבָאָה הִיא, וְתִהְיֶה כֵן לְכֻלְּכֶם, כִּי תָבֹאוּ וְתָשׁוּבוּ אִישׁ אֶל אֲחֻזָּתוֹ וְאִישׁ אֶל מִשְׁפַּחְתּוֹ. וְחָזַר וְאָמַר "יוֹבֵל הִיא שְׁנַת הַחֲמִשִּׁים שָׁנָה תִּהְיֶה לָכֶם" (ויקרא כ"ה:י"א), שֶׁתִּהְיֶה לָכֶם שְׁנַת הַחֲמִשִּׁים שָׁנָה לְיוֹבֵל, לֹא לְדָבָר אַחֵר, וְלֹא תִזְרְעוּ וְלֹא תִקְצְרוּ, אֲבָל תִּהְיֶה קֹדֶשׁ וְתָשׁוּבוּ אִישׁ אֶל אֲחֻזָּתוֹ, לִהְיוֹתָהּ לְכֻלְּכֶם יוֹבֵל כִּשְׁמָהּ. וְעַל דֶּרֶךְ הָאֱמֶת, "דְּרוֹר" מִלְּשׁוֹן "דּוֹר הֹלֵךְ וְדוֹר בָּא" (קהלת א ד), וְכֵן "יוֹבֵל" שֶׁיָּשׁוּב אֶל הַיּוֹבֵל אֲשֶׁר שָׁם שָׁרָשָׁיו, וְהִיא תִּהְיֶה לָכֶם:
@12 **מִן הַשָּׂדֶה תֹּאכְלוּ** עַל יְדֵי הַשָּׂדֶה תֹּאכְלוּ מִן הַבַּיִת, שֶׁאִם כָּלָה לַחַיָּה מִן הַשָּׂדֶה אַתָּה צָרִיךְ לְבַעֵר מִן הַבַּיִת כְּשֵׁם שֶׁנֶּאֱמַר בַּשְּׁבִיעִית, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:י"ב). וְאִם כֵּן לֹא יִהְיֶה הַפָּסוּק מְחֻבָּר, אֲבָל יֹאמַר לֹא תִזְרָעוּ וְלֹא תִקְצְרוּ כִּי יוֹבֵל הִיא קֹדֶשׁ תִּהְיֶה לָכֶם, וּמִן הַשָּׂדֶה תֹּאכְלוּ אֶת תְּבוּאָתָהּ לֹא מִן הַבַּיִת. וְר"א אָמַר (אבן עזרא על ויקרא כ"ה:י"ב) "מִן הַשָּׂדֶה תֹּאכְלוּ" מִמַּה שֶׁתּוֹצִיא הַשָּׂדֶה מֵעַצְמָהּ תֹּאכְלוּ כֻּלְּכֶם, כַּכָּתוּב בִּשְׁנַת הַשְּׁמִטָּה. וּלְדַעְתִּי יֹאמַר לֹא תִקְצְרוּ וְלֹא תִבְצְרוּ בַּשָּׁנָה הַזֹּאת כִּי יוֹבֵל הִיא וְקֹדֶשׁ תִּהְיֶה לָכֶם, מִן הַשָּׂדֶה תָּבִיאוּ הַתְּבוּאָה וְתֹאכְלוּ, שֶׁתֵּצְאוּ הַשָּׂדֶה לִלְקֹט וְלֶאֱכֹל עִם הָעֲנִיִּים וְהָאֶבְיוֹנִים הַחַיָּה וְהַבְּהֵמָה, לֹא שֶׁיִּהְיֶה לָכֶם עֵת קָצִיר וּבָצִיר וְתַאַסְפוּ לָכֶם אֶל הַבַּיִת וְאֶל הָאוֹצָרוֹת כִּתְבוּאַת שְׁאָר הַשָּׁנִים. וּמַה שֶׁשָּׁנוּ בְּתוֹרַת כֹּהֲנִים (פרק ג ה), מִכָּאן אָמְרוּ הַכּוֹבֵשׁ שְׁלֹשָׁה כְּבָשִׁים בְּחָבִית אַחַת, רַבִּי אֱלִיעֶזֶר אוֹמֵר אוֹכְלִין עַל הָרִאשׁוֹן, וְרַבִּי יְהוֹשֻׁעַ אוֹמֵר אַף עַל הָאַחֲרוֹן, רַבָּן גַּמְלִיאֵל אוֹמֵר כָּל שֶׁכָּלָה מִינוֹ מִן הַשָּׂדֶה יְבַעֵר מִינוֹ מִן הַבַּיִת, וַהֲלָכָה כִּדְבָרָיו, רַבִּי שִׁמְעוֹן אוֹמֵר כָּל יָרָק אֶחָד לַבִּעוּר. וְכָל זֶה מִדְרָשׁ מִפְּנֵי שֶׁלֹּא אָמַר "מִן הַשָּׂדֶה תָּבִיאוּ וְתֹאכְלוּ", וְסָמַךְ הָאֲכִילָה בַּשָּׂדֶה שֶׁלֹּא יֹאכְלוּ אֶלָּא בּוֹ. וְיִתָּכֵן שֶׁהוּא סֶמֶךְ מִדִּבְרֵיהֶם, וּלְכָךְ הָיָה רַבִּי יְהוֹשֻׁעַ מֵקֵל בּוֹ וְרַבָּן גַּמְלִיאֵל מֵקֵל בְּטַעְמוֹ. וּכְבָר כָּתַבְתִּי זֶה לְמַעְלָה (רמב"ן על ויקרא כ"ה:ז'). וְאֶפְשָׁר לְדִבְרֵי רַבָּן גַּמְלִיאֵל שֶׁמִּצְוַת הַבִּעוּר מִן הַתּוֹרָה, אֲבָל הַטַּעַם כֵּיוָן שֶׁנִּבְלַע מִתְּחִלָּה מְבֹעָר הוּא:
@14 **אַל תּוֹנוּ** זוֹ אוֹנָאַת מָמוֹן. **בְּמִסְפַּר שָׁנִים אַחַר הַיּוֹבֵל** פְּשׁוּטוֹ שֶׁל מִקְרָא עַל אָפְנָיו עַל הָאוֹנָאָה בָּא לְהַזְהִיר, כְּשֶׁתִּמְכֹּר אוֹ תִקְנֶה קַרְקַע דַּע כַּמָּה שָׁנִים יֵשׁ עַד הַיּוֹבֵל וּלְפִי הַשָּׁנִים יִמְכֹּר הַמּוֹכֵר וְיִקְנֶה הַקּוֹנֶה, שֶׁהֲרֵי סוֹפוֹ לְהַחְזִיר לוֹ בִּשְׁנַת הַיּוֹבֵל, וְאִם יֵשׁ שָׁנִים מֻעָטוֹת וְזֶה מוֹכְרָהּ בְּדָמִים יְקָרִים הֲרֵי נִתְאַנָּה לוֹקֵחַ, וְאִם יֵשׁ שָׁנִים מְרֻבּוֹת וְיֹאכַל מִמֶּנָּה תְּבוּאוֹת הַרְבֵּה צָרִיךְ לִקְנוֹתָהּ לְפִי הַזְּמַן. וְזֶהוּ שֶׁנֶּאֱמַר (כאן) "בְּמִסְפַּר שְׁנֵי תְבוּאֹת יִמְכָּר לָךְ", לְפִי מִנְיַן שְׁנֵי הַתְּבוּאוֹת שֶׁתְּהֵא עוֹמֶדֶת בְּיַד הַלּוֹקֵחַ תִּמְכֹּר לוֹ. וְרַבּוֹתֵינוּ דָּרְשׁוּ (ערכין כט) מִכָּאן, שֶׁהַמּוֹכֵר שָׂדֵהוּ אֵינוֹ מֻתָּר לִגְאֹל פָּחוֹת מִשְׁתֵּי שָׁנִים, אֲפִילּוּ יֵשׁ שָׁלֹשׁ תְּבוּאוֹת בְּאוֹתָן שְׁתֵּי שָׁנִים. וְאֵינוֹ יוֹצֵא מִפְּשׁוּטוֹ, מִסְפַּר שָׁנִים שֶׁל תְּבוּאוֹת וְלֹא שֶׁל שִׁדָּפוֹן, וּמִעוּט שָׁנִים שְׁתַּיִם, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:ט"ו). וּבֶאֱמֶת שֶׁהוּא הַנָּכוֹן בְּיִשּׁוּב הַמִּקְרָא. אֲבָל רַבּוֹתֵינוּ אָמְרוּ (ב"מ נו) שֶׁאֵין אוֹנָאָה לַקַּרְקָעוֹת, שֶׁנֶּאֱמַר "אוֹ קָנֹה מִיַּד עֲמִיתֶךָ" - דָּבָר הַנִּקְנֶה מִיָּד לְיָד, וְהַמִּקְרָא הַזֶּה כְּפִי פְּשׁוּטוֹ וּלְפִי מִדְרָשׁוֹ לְדִבְרֵי הָרַב בְּקַרְקָעוֹת הוּא, אֲבָל עַל כָּרְחֵנוּ נִצְטָרֵךְ לְהַטּוֹת מִקְרָאוֹת מִפְּשׁוּטָן וְנֹאמַר שֶׁיִּהְיֶה כָּל פָּסוּק עוֹמֵד בְּעַצְמוֹ, יֹאמַר "וְכִי תִמְכְּרוּ מִמְכָּר לַעֲמִיתֶךָ אוֹ קָנֹה מִיַּד עֲמִיתֶךָ" דָּבָר הַנִּקְנֶה מִיָּד לְיָד, "אַל תּוֹנוּ אִישׁ אֶת אָחִיו", וְיַחְזֹר וְיֹאמַר, בְּמִסְפַּר שָׁנִים אַחַר הַיּוֹבֵל תִּקְנֶה מֵאִתּוֹ הַתְּבוּאוֹת, וּכְמִסְפַּר שְׁנֵי הַתְּבוּאוֹת יִמְכְּרֵם לָךְ, כְּפִי הַשָּׁנִים תַּרְבֶּה וְתַמְעִיט, כִּי עַל כָּל פָּנִים תְּשִׁיבֶנּוּ לוֹ בַּיּוֹבֵל. וְכָל זֶה אַזְהָרָה בַּיּוֹבֵל שֶׁיִּזָּהֲרוּ בּוֹ לְעוֹלָם. וְחָזַר וְאָמַר "וְלֹא תוֹנוּ אִישׁ אֶת עֲמִיתוֹ" (ויקרא כ"ה:י"ז) בִּדְבָרִים. וַאֲנִי חוֹשֵׁב עוֹד סְבָרָא, שֶׁוַּדַּאי הַמְאַנֶּה אֶת חֲבֵרוֹ לְדַעַת עוֹבֵר בְּלָאו בֵּין בְּמִטַּלְטְלִים בֵּין בְּקַרְקָעוֹת, שֶׁבָּהֶן דִּבֵּר הַכָּתוּב "אַל תּוֹנוּ אִישׁ אֶת אָחִיו בְּמִסְפַּר שָׁנִים אַחַר הַיּוֹבֵל", שֶׁהוּא מַזְהִיר שֶׁיִּקְנוּ וְיִמְכְּרוּ לְפִי הַשָּׁנִים וְלֹא יוֹנוּ אִישׁ אֶת אָחִיו, אֲבָל רַבּוֹתֵינוּ חִדְּשׁוּ בָּאוֹנָאָה תַּשְׁלוּמִים בִּשְׁתוּת הַמִּקָּח וּבִטּוּל מִקָּח בְּיוֹתֵר מִשְּׁתוּת, וּמִזֶּה בִּלְבַד מִעֲטוּ הַקַּרְקָעוֹת, לְפִי שֶׁהָאוֹנָאָה בָּהֶם אֲפִלּוּ בְּיָתֵר מִשְּׁתוּת - מְחִילָה, כְּמוֹ שֶׁהִיא מְחִילָה בְּמִטַּלְטְלִים בְּפָחוֹת מִשְּׁתוּת, אע"פ שֶׁהוּא אָסוּר לְהוֹנוֹת כֵּן לְדַעַת, אֲבָל אֵין דֶּרֶךְ בְּנֵי אָדָם לְבַטֵּל מִמְכָּרָם מִפְּנֵי אוֹנָאָה מוּעֶטֶת כָּזוֹ. וְדָרְשׁוּ חֲכָמִים מִפְּנֵי שֶׁאָמַר הַכָּתוּב "וְכִי תִמְכְּרוּ מִמְכָּר לַעֲמִיתֶךָ אוֹ קָנֹה" דָּבָר הַנִּקְנֶה מִיָּד לְיָד, "אַל תּוֹנוּ אִישׁ אֶת אָחִיו", לָמַדְנוּ שֶׁיֵּשׁ בְּאוֹנָאָה דִּין מְיֻחָד בְּמִטַּלְטְלִים שֶׁאֵינוֹ נוֹהֵג בְּקַרְקָעוֹת, וְהוּא חֲזָרַת הַמָּמוֹן, אֲבָל אַזְהָרַת הַלָּאו נוֹהֶגֶת בְּכֻלָּן. וּלְכָךְ אָמַר "וְכִי תִמְכְּרוּ מִמְכָּר" לְשׁוֹן רַבִּים, לְמוֹכֵר קַרְקָעוֹת וּלְמוֹכֵר מִטַּלְטְלִין, "אוֹ קָנֹה מִיַּד עֲמִיתֶךָ" - הַיָּחִיד מֵהֶם, הַמּוֹכֵר הַמִּטַּלְטְלִין מִיָּד לְיָד, וְאָמַר לְכֻלָּן "אַל תּוֹנוּ", וְכֵיוָן שֶׁיִּחֵד וְהִפְרִישׁ הַמִּטַּלְטְלִין רִבָּה בָּהֶן דִּין אוֹנָאָה, וְהִיא בַּחֲזָרַת הַתַּשְׁלוּמִין. וְזֶה דָּבָר נָכוֹן כְּפִי הַמִּדְרָשִׁים שֶׁקִּבְּלוּ רַבּוֹתֵינוּ בְּרִמְזֵי הַתּוֹרָה. וְאוּלַי יִהְיֶה כָּל זֶה אַסְמַכְתָּא, כִּי הַלָּאו אַזְהָרָה בֵּין בְּקַרְקַע בֵּין בְּמִטַּלְטְלִין, וַחֲזָרַת הַמָּמוֹן בְּיָדָם קַבָּלָה בְּמִטַּלְטְלִין וְלֹא בְּקַרְקָעוֹת, כְּמוֹ שֶׁאָמְרוּ (ב"ק יד) דָּבָר הַשָּׁוֶה לְכָל כֶּסֶף, כִּי הַשִּׁעוּרִים כֻּלָּם בִּשְׁתוּת וְיָתֵר עַל שְׁתוּת כְּפִי דֵּעוֹת בְּנֵי אָדָם, וְלָמָּה לֹא יוֹצִיאוּ הַקַּרְקָעוֹת מִן הַדִּין הַזֶּה וְהֵם הוֹצִיאוּ מִמֶּנּוּ כְּלֵי בַּעַל הַבַּיִת וְאָמְרוּ (ב"מ נא), לֹא שָׁנוּ אֶלָּא בְּלוֹקֵחַ מִן הַתַּגָּר אֲבָל בְּלוֹקֵחַ מִבַּעַל הַבַּיִת אֵין לוֹ אוֹנָאָה, מִפְּנֵי שֶׁדֶּרֶךְ בַּעֲלֵי בָּתִּים שֶׁלֹּא יִמְכְּרוּ כְּלֵי תַּשְׁמִישָׁן. וְגַם יִתָּכֵן לוֹמַר כִּי הַכָּתוּב יַזְהִיר שֶׁיֵּדְעוּ מִסְפַּר הַשָּׁנִים עַד הַיּוֹבֵל וּלְפִיהֶם יִמְכְּרוּ וְיִקְנוּ, וְלֹא יוֹנוּ בָּהֶם אִישׁ אֶת אָחִיו לְהַטְעוֹתוֹ בַּמִּסְפָּר אוֹ לְהַטְעוֹתוֹ בַּמְּכִירָה שֶׁיַּחְשֹׁב בָּהּ שֶׁהִיא לַחֲלוּטִין וְיַטְעֵהוּ בְּכָךְ, אֲבָל יֵדְעוּ שְׁנֵיהֶם וְיוֹדִיעוּ זֶה לָזֶה הַמִּסְפָּר כִּי הַמְּכִירָה הִיא בְּמִסְפַּר שָׁנִים עַד הַיּוֹבֵל, שֶׁגַּם בְּקַרְקָעוֹת יֵשׁ אוֹנָאָה בְּטוֹעִים בַּמִּדָּה וּבַמִּנְיָן וַאֲפִלּוּ בְּפָחוֹת מִשְּׁתוּת, וְכָל שֶׁכֵּן בְּמִטַּלְטְלִין:
@18 **וַעֲשִׂיתֶם אֶת חֻקֹּתַי וְאֶת מִשְׁפָּטַי תִּשְׁמְרוּ** יַזְהִיר בַּחֻקִּים מִפְּנֵי הַשְּׁמִטָּה וְהַיּוֹבֵל הַנִּזְכָּרִים, לְפִי שֶׁהֵם מִכְּלַל הַחֻקִּים, וְהַמִּשְׁפָּטִים מִפְּנֵי דִּין חֲזָרַת הַמִּמְכָּרִים וְהָעֲבָדִים בַּיּוֹבֵל וְהָאוֹנָאָה. וְאָמַר "וִישַׁבְתֶּם עַל הָאָרֶץ לָבֶטַח", שֶׁבַּעֲוֹן שְׁמִטָּה וְיוֹבֵל יִשְׂרָאֵל גּוֹלִים (אבות ה:ט). וְחָזַר וְאָמַר "וְנָתְנָה הָאָרֶץ פִּרְיָהּ וְגוֹ' וִישַׁבְתֶּם לָבֶטַח עָלֶיהָ" (ויקרא כ"ה:י"ט), שֶׁלֹּא תִּצְטָרְכוּ לָצֵאת מִמֶּנָּה בַּשְּׁבִיעִית לָגוּר בְּאֶרֶץ אַחֶרֶת מִפְּנֵי חֹסֶר לֶחֶם:
@20 **וְכִי תֹאמְרוּ מַה נֹּאכַל בַּשָּׁנָה הַשְּׁבִיעִת** כְּמוֹ מְסֹרָס, וְכִי תֹּאמְרוּ בַּשָּׁנָה הַשְּׁבִיעִית מַה נֹּאכַל, כִּי הַדְּאָגָה לָהֶם בַּעֲבוּר הַשְּׁמִינִית, כִּי כֵּיוָן שֶׁתְּחִלַּת שְׁנַת הַשְּׁמִטָּה וְהַיּוֹבֵל מִתִּשְׁרֵי, מִפֵּרוֹת הַשִּׁשִּׁית יֹאכְלוּ בַּשְּׁבִיעִית כַּמִּנְהָג בְּכָל הַשָּׁנִים לֶאֱכֹל עַד אַחֲרֵי הַקָּצִיר שֶׁהוּא בְּחַג הַשָּׁבוּעוֹת, וְגַם אַחֲרֵי כֵן עַד כְּלוֹת מְלֶאכֶת הַתְּבוּאוֹת לִזְרוֹת וּלְהָבֵר. וְעַל כֵּן הַנָּכוֹן בְּפֵרוּשׁ "וְעָשָׂת אֶת הַתְּבוּאָה לִשְׁלֹשׁ הַשָּׁנִים", בַּעֲבוּר שְׁנַת הַיּוֹבֵל, שֶׁתַּעֲשֶׂה הַשִּׁשִּׁית לְכָל שְׁנַת הַשְּׁמִטָּה וְהַיּוֹבֵל וְהַשָּׁנָה שֶׁאַחֲרֵי הַיּוֹבֵל, כִּי כֻּלָּם יָשָׁן יֹאכֵלוּ. וְהִבְטִיחַ הַכָּתוּב כִּי תִּפְחֲדוּ בַּשָּׁנָה הַשְּׁבִיעִית לֵאמֹר מַה נֹּאכַל, אֲנִי אֲצַוֶּה אֶת בִּרְכָתִי בַּשָּׁנָה הַשִּׁשִּׁית שֶׁתַּעֲשֶׂה הַתְּבוּאָה לִשְׁלֹשׁ הַשָּׁנִים הַבָּאִים אַחֲרֵיהֶם, וְהִיא תּוֹסֶפֶת בְּרָכָה כְּדֵי שֶׁתַּסְפִּיק גַּם בַּשְּׁמִטָּה וְהַיּוֹבֵל. וְאָמַר "וּזְרַעְתֶּם אֵת הַשָּׁנָה הַשְּׁמִינִת", לוֹמַר שֶׁתִּזְרְעוּ בַּשָּׁנָה הַשְּׁמִינִית כְּמִנְהַג הָאָרֶץ, וְלֹא תְּמַהֲרוּ לַחֲרֹשׁ וְלִזְרֹעַ וְלֹא לִקְצֹר, כִּי עַד בֹּא תְּבוּאָתָהּ לַבַּיִת בְּעֵת אֹסֶף הַשָּׁנִים בְּחַג הַסֻּכּוֹת תֹּאכְלוּ יָשָׁן. וּבְתוֹרַת כֹּהֲנִים (פרק ד ו), "לִשְׁלֹשׁ הַשָּׁנִים" - לַשִּׁשִּׁית וְלַשְּׁבִיעִית וּלְמוֹצָאֵי שְׁבִיעִית. דָּבָר אַחֵר "לִשְׁלֹשׁ הַשָּׁנִים" - לַשְּׁבִיעִית וְלַיּוֹבֵל וּלְמוֹצָאֵי יוֹבֵל:
@23 **וְהָאָרֶץ לֹא תִמָּכֵר לִצְמִתֻת** לִתֵּן לָאו עַל חֲזָרַת שָׂדוֹת לַבְּעָלִים בַּיּוֹבֵל, שֶׁלֹּא יְהֵא לוֹקֵחַ כּוֹבְשָׁהּ, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:כ"ג). וְאִם כֵּן לָמָּה יַזְהִיר בַּמְּכִירָה, וְהָרָאוּי "לֹא תִקָּנֶה לִצְמִיתוּת". וְאוּלַי יֹאמַר לֹא תִּמָּכֵר לָכֶם לִצְמִיתוּת. וְכֵן "לֹא יִמָּכְרוּ מִמְכֶּרֶת עָבֶד" (ויקרא כ"ה:מ"ב), אַזְהָרָה בַּלּוֹקֵחַ שֶׁיּוֹצִיאֶנּוּ בַּיּוֹבֵל כְּפִי פְּשׁוּטוֹ. וְיִתָּכֵן שֶׁיִּהְיֶה "לֹא תִמָּכֵר לִצְמִיתוּת" לָאו בַּמּוֹכֵר שֶׁלֹּא יִמְכְּרֶנָּה לַחֲלוּטִין, לוֹמַר הֲרֵנִי מוֹכְרָהּ לְךָ לְעוֹלָמִים גַּם אַחֲרֵי הַיּוֹבֵל, וְאע"פ שֶׁהַיּוֹבֵל מַפְקִיעָהּ הִזְהִיר הַכָּתוּב לַמּוֹכֵר אוֹ לִשְׁנֵיהֶם שֶׁלֹּא יַעֲשׂוּ מִמְכָּרָם לִצְמִיתוּת, וְאִם אָמְרוּ כֵן יַעַבְרוּ בַּלָּאו הַזֶּה, וְלֹא יוֹעִיל לָהֶם כִּי תַּחְזֹר בַּיּוֹבֵל. וְכָךְ פֵּרְשׁוֹ הָרַב רַבִּי מֹשֶׁה (הל' שמיטה ויובל פי"א ה"א). וְהַטַּעַם בָּזֶה, כִּי בְּיָדוּעַ בְּדֵעוֹת בְּנֵי אָדָם שֶׁאִם יַעֲשׂוּ מִמְכָּרָם מִתְּחִלָּה כְּמִסְפַּר שָׁנִים עַד הַיּוֹבֵל, יֵקַל בְּעֵינֵיהֶם הָעִנְיָן, וְאִם יִקָּנֶה לַחֲלוּטִין תִּקְשֶׁה בְּעֵינָיו הַחֲזָרָה מְאֹד, וְיִהְיֶה כְּעִנְיָן שֶׁאָמְרוּ (תמורה ד), מַאי דְּאָמַר רַחֲמָנָא לָא תַּעֲבֵד, אִי עָבַד לָא מְהַנֵּי, וְלָקֵי מִשּׁוּם דְּעָבַר אַהֻרְמָנָא דְּמַלְכָּא. וְהַנָּכוֹן בְּעֵינַי שֶׁאֵין זֶה לָאו לִלְקוֹת עָלָיו, אֲבָל הוּא טַעַם, יֹאמַר, הַנְהִיגוּ בֵּינֵיכֶם הַיּוֹבֵל וְאַל יִקְשֶׁה בְּעֵינֵיכֶם, "כִּי לִי הָאָרֶץ", וְאֵינִי רוֹצֶה שֶׁתִּמָּכֵר לִצְמִיתוּת כִּשְׁאָר הַמִּמְכָּרִים. וְזוֹ הִיא כַּוָּנָתָם בְּתוֹרַת כֹּהֲנִים (פרק ד ח), "לִצְמִיתוּת" - לַחֲלוּטִין. "כִּי לִי הָאָרֶץ" - אַל תֵּרַע עֵינְךָ בָהּ. "כִּי גֵרִים וְתוֹשָׁבִים אַתֶּם" - אַל תַּעֲשׂוּ עַצְמְכֶם עִקָּר. "אַתֶּם עִמָּדִי" - דַּיּוֹ לָעֶבֶד שֶׁיְּהֵא כְּרַבּוֹ, כְּשֶׁהִיא שֶׁלִּי הֲרֵי הִיא שֶׁלָּכֶם. וְטַעַם "כִּי לִי הָאָרֶץ" עַל דֶּרֶךְ הָאֱמֶת, כְּמוֹ "וְיִקְחוּ לִי תְּרוּמָה" (שמות כה ב), וְזֶהוּ שֶׁרָמְזוּ כָּאן דַּיּוֹ לָעֶבֶד שֶׁיְּהֵא כְּרַבּוֹ, כִּי יִהְיֶה הַיּוֹבֵל נוֹהֵג בָּעוֹלָם. וְהַמַּשְׂכִּיל יָבִין:
@24 **וּבְכֹל אֶרֶץ אֲחֻזַּתְכֶם** לְרַבּוֹת בָּתִּים וְעֶבֶד עִבְרִי, וְדָבָר זֶה מְפֹרָשׁ בְּקִדּוּשִׁין בְּפֶרֶק רִאשׁוֹן (כא). וּלְפִי פְּשׁוּטוֹ סָמוּךְ עַל פָּרָשָׁה שֶׁל אַחֲרָיו, שֶׁהַמּוֹכֵר רַשַּׁאי לְגָאֳלָהּ לְאַחַר שְׁתֵּי שָׁנִים אוֹ הוּא אוֹ קְרוֹבוֹ, וְאֵין הַלּוֹקֵחַ יָכוֹל לְעַכֵּב, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:כ"ד). וְאֵינוֹ נָכוֹן בְּעֵינַי שֶׁיִּכְלֹל בְּפָרָשַׁת הַיּוֹבֵל וּבְכֹל אֶרֶץ אֲחֻזַּתְכֶם תִּתְּנוּ גְּאֻלָּה וְיֹאמַר בַּפָּרָשָׁה הַשְּׁנִיָּה כֵּיצַד, "כִּי יָמוּךְ אָחִיךָ" וְגוֹ'. וְהַנָּכוֹן בְּעֵינַי שֶׁיֹּאמַר וּבְכֹל אֶרֶץ אֲחֻזַּתְכֶם, הָאָרֶץ אֲשֶׁר אֲנִי נֹתֵן לָכֶם לַאֲחֻזָּה, תִּתְּנוּ הַגְּאֻלָּה הַזֹּאת שֶׁל הַיּוֹבֵל. וְאָמַר "גְּאֻלָּה" כְּמוֹ "גָּאַל ה' עַבְדּוֹ יַעֲקֹב" (ישעיהו מח כ), שֶׁהוֹצִיא עַבְדּוֹ מִיַּד הַמַּחֲזִיקִים בּוֹ, וְכֵן "וְגָאַלְתִּי אֶתְכֶם בִּזְרוֹעַ נְטוּיָה" (שמות ו ו), אַף זֶה תִּתְּנוּ גְּאֻלָּה לָאָרֶץ, שֶׁאֲנִי רוֹצֶה לִגְאֹל אַרְצִי מִיַּד הַמַּחֲזִיקִים בָּהּ, שֶׁלֹּא נְתַתִּיהָ אֲנִי לָהֶם בְּחֵלֶק אֲחֻזָּתָם. וְהֻצְרַךְ לוֹמַר כֵּן בַּעֲבוּר שֶׁאָמַר "כִּי לִי הָאָרֶץ" (ויקרא כ"ה:כ"ג), וְהִנֵּה כָּל הָאָרֶץ לוֹ הִיא, לְפִיכָךְ חָזַר וּפֵרֵשׁ שֶׁיִּנְהֹג הַיּוֹבֵל בְּאֶרֶץ אֲחֻזָּתֵנוּ בִּלְבַד, לֹא בְּחוּצָה לָאָרֶץ, וְאָמַר "וּבְכֹל" שֶׁהִיא תִּנְהַג בְּכָל אֲחֻזָּתֵנוּ גַּם בְּעֵבֶר הַיַּרְדֵּן וּבְכָל מְקוֹם הָאֲחֻזָּה, לֹא בְּאֶרֶץ ה' אֲשֶׁר שָׁם הַמִּקְדָּשׁ בִּלְבַד:
@29 **וְאִישׁ כִּי יִמְכֹּר בֵּית מוֹשַׁב עִיר חוֹמָה** בַּעֲבוּר שֶׁמִּמְכַּר בֵּיתוֹ שֶׁל אָדָם קָשֶׁה בְּעֵינָיו מְאֹד, וְיֵבוֹשׁ מִמֶּנּוּ בְּעֵת שֶׁיִּמְכְּרֶנּוּ, רָצְתָה הַתּוֹרָה שֶׁיִּגְאָלֶנּוּ בְּתוֹךְ הַשָּׁנָה הָרִאשׁוֹנָה. וּבַעֲבוּר כִּי הָאָדָם לְשָׂדֶה נֶעֱבָד וּמִמֶּנּוּ יֵצֵא לֶחֶם לְמִחְיָתוֹ, רָצָה שֶׁיֵּצֵא הַשָּׂדֶה בַּיּוֹבֵל. אֲבָל הַבַּיִת לְאַחַר הַיֵּאוּשׁ שֶׁשִּׁנָּה דִּירָתוֹ וְעָמַד שָׁנָה בְּבַיִת אַחֵר, לֹא יַזִּיק לוֹ, כִּי לֹא תִּמְעַט מִחְיָתוֹ אִם יֵחָלֵט. וּבָתֵּי הַחֲצֵרִים עֲשׂוּיִים לִשְׁמִירַת הַשָּׂדוֹת וְלִהְיוֹתָם מוֹשָׁב לְעוֹבְדֵי הָאֲדָמָה, וְעַל כֵּן דִּינָם כִּשְׂדֵה הָאָרֶץ:
@33 **וַאֲשֶׁר יִגְאַל מִן הַלְוִיִּם** הַנִּרְאֶה בִּפְשׁוּטוֹ שֶׁל פָּסוּק זֶה כִּי אָמַר "גְּאֻלַּת עוֹלָם תִּהְיֶה לַלְוִיִּם" (ויקרא כ"ה:ל"ב), לִגְאֹל מִיָּד וְלִגְאֹל לְעוֹלָם, וְלֹא פֵּרֵשׁ בָּהֶם אִם יִגְאֲלוּ הַקְּרוֹבִים וְלֹא אִם יִנְהַג בָּהֶם יוֹבֵל. לְפִיכָךְ חָזַר וְאָמַר, "וַאֲשֶׁר יִגְאַל מִן הַלְוִיִּם", יִהְיֶה הַגּוֹאֵל שֶׁיִּגְאַל הוּא מֵעַצְמוֹ אוֹ הַלֵּוִי הַקָּרוֹב אֵלָיו, "וְיָצָא מִמְכַּר בַּיִת וְעִיר אֲחֻזָּתוֹ בַּיֹּבֵל" מִיַּד הַקּוֹנֶה, עַל דַּעַת כֵּן יִגְאַל שֶׁיַּחְשֹׁב שְׁנֵי מִמְכָּרוֹ וְהֵשִׁיב אֶת הָעֹדֵף, לוֹמַר שֶׁהַיּוֹבֵל נוֹהֵג בָּהֶם וְתִהְיֶה גְּאֻלַּת הַלְוִיִּם כַּאֲשֶׁר אָמַר בְּיִשְׂרָאֵל "וְחִשַּׁב אֶת שְׁנֵי מִמְכָּרוֹ" וְגוֹ' (ויקרא כ"ה:כ"ז). וְרַבּוֹתֵינוּ אָמְרוּ (ערכין לג) שֶׁהַכָּתוּב מְדַבֵּר בְּלֵוִי שֶׁקָּנָה מִלֵּוִי. וּלְפִי דִּבְרֵיהֶם נִרְאֶה לִי בְּפֵרוּשׁ הַפָּסוּק כִּי הָיָה לְפָנִים בְּיִשְׂרָאֵל כְּשֶׁצָּרִיךְ אָדָם לִמְכֹּר שָׂדֵהוּ שֶׁיָּבֹא הַקּוֹדֵם בִּירֻשָּׁתוֹ וְיִקְנֶה אוֹתָהּ, וְהוּא הַנִּקְרָא "גְּאֻלָּה" שֶׁנֶּאֱמַר "קְנֵה לְךָ אֶת שָׂדִי אֲשֶׁר בַּעֲנָתוֹת כִּי לְךָ מִשְׁפַּט הַגְּאֻלָּה לִקְנוֹת" (ירמיהו לב ז). וְכֵן מְפֹרָשׁ עוֹד בְּעִנְיַן בֹּעַז (רות ד). וְנִרְאֶה בְּעֵינַי שֶׁהָיוּ דָּנִים לוֹ דִּין קְדִימָה כַּאֲשֶׁר הִנְהִיגוּ לָנוּ רַבּוֹתֵינוּ בְּדִינָא דְּבַר מִצְרָא, וְהָיוּ קוֹנִים מִן הַגּוֹאֵל הָרִאשׁוֹן בְּקִנְיַן סוּדָר כְּמוֹ שֶׁעָשָׂה בֹּעַז (שם שם ח). וְהִנֵּה יֹאמַר הַכָּתוּב בְּכָאן כִּי כַּאֲשֶׁר יִגְאַל הַלֵּוִי נַחֲלַת הַלֵּוִי קְרוֹבוֹ, כְּלוֹמַר שֶׁיִּקְנֶה אוֹתָהּ מִמֶּנּוּ כְּדִין הַגְּאֻלָּה, יֵצֵא הַמִּמְכָּר הַהוּא בַּיּוֹבֵל; לִמֵּד שֶׁיְּהֵא יוֹבֵל נוֹהֵג בָּהֶם בִּגְאֻלָּה כִּמְכִירָה אַחֶרֶת. וְלֹא הָיָה צָרִיךְ לְהַזְכִּיר הַדִּין בַּמְּכִירָה לְבַדָּהּ כִּי הֵם בִּכְלַל יִשְׂרָאֵל, אֶלָּא שֶׁיִּפָּה כֹּחָם בִּגְאֻלַּת עוֹלָם. וְהַדִּין הַזֶּה שֶׁל גְּאֻלָּה גַּם בְּיִשְׂרָאֵל הוּא נוֹהֵג, אֲבָל הִזְכִּירוֹ הַכָּתוּב בַּלְוִיִּם שֶׁלֹּא תֹּאמַר לֹא נִתְּנוּ הֶעָרִים אֶלָּא לְשֵׁבֶט הַלֵּוִי כֻּלּוֹ, וְלָכֵן יֵצְאוּ מִיִּשְׂרָאֵל אֲבָל לֹא מִלֵּוִי, וְכָל שֶׁכֵּן מִגּוֹאֵל קָרוֹב שֶׁאֲנַחְנוּ חִיַּבְנוּהוּ לִקְנוֹת, וּלְכָךְ אָמַר שֶׁאַף הַגְּאֻלָּה תֵּצֵא בַּיּוֹבֵל, וּמִן הַלֵּוִי נִלְמוֹד לְיִשְׂרָאֵל. וְאֶפְשָׁר גַּם כֵּן שֶׁאֵין הַלְוִיִּם רַשָּׁאִין לִמְכֹּר בְּעָרֵיהֶם לְיִשְׂרָאֵל בְּשׁוּם מֶכֶר, וְלָכֵן תִּקָּרֵא כָּל קְנִיָּתָם "גְּאֻלָּה":
@35 וְטַעַם **וְחֵי אָחִיךָ עִמָּךְ** שֶׁיִּחְיֶה עִמָּךְ, וְהִיא מִצְוַת עֲשֵׂה לְהַחֲיוֹתוֹ שֶׁמִּמֶּנָּה נִצְטַוֵּינוּ עַל פִּקּוּחַ נֶפֶשׁ בְּמִצְוַת עֲשֵׂה. וּמִכָּאן אָמְרוּ (תו"כ פרשה ה ג), "וְחֵי אָחִיךָ עִמָּךְ" זוֹ דָּרַשׁ בֶּן פּוֹטִירִי, שְׁנַיִם שֶׁהָיוּ מְהַלְּכִין בַּדֶּרֶךְ וּבְיַד אֶחָד מֵהֶם קִיתוֹן שֶׁל מַיִם, אִם שׁוֹתֶה הוּא מַגִּיעַ לַיִּשּׁוּב וְאִם שְׁנֵיהֶם שׁוֹתִים שְׁנֵיהֶם מֵתִים, דָּרַשׁ בֶּן פּוּטִירִי מוּטָב יִשְׁתּוּ שְׁנֵיהֶם וְיָמוּתוּ וְלֹא יִרְאֶה אֶחָד בְּמִיתָתוֹ שֶׁל חֲבֵרוֹ; עַד שֶׁבָּא רַבִּי עֲקִיבָא וְלִמֵּד, "וְחֵי אָחִיךָ עִמָּךְ" - חַיֶּיךָ קוֹדְמִים לְחַיֵּי חֲבֵרֶךָ. וְחָזַר וְאָמַר (ויקרא כ"ה:ל"ו), "וְחֵי אָחִיךָ עִמָּךְ" לְחַזֵּק וּלְהַזְהִיר. וּמִדְרָשׁוֹ (ב"מ סב), אַהְדַּר לֵיהּ רִבִּית דְּלֶחְיֵי עִמָּךְ; צִוָּה בְּהַחְזָרַת רִבִּית קְצוּצָה, כְּעִנְיָן שֶׁאָמַר בְּגֶזֶל (ויקרא ה':כ"ג) "וְהֵשִׁיב אֶת הַגְּזֵלָה אֲשֶׁר גָּזָל". וְאוּנְקְלוֹס (תרגום אונקלוס על ויקרא כ"ה:ל"ה) עָשָׂה "גֵּר וְתוֹשָׁב וָחַי עִמָּךְ" הַכֹּל מִן הַמִּצְוָה, "יְדוּר וְיִתּוֹתַב וְיֵחֵי עִמָּךְ". אֲבָל עַל דַּעַת רַבּוֹתֵינוּ בַּגְּמָרָא (ב"מ עא), וְהֶחֱזַקְתָּ בּוֹ וּבְגֵר וְתוֹשָׁב, וְחֵי כָּל אֶחָד מֵהֶם עִמָּךְ:
@36 **נֶשֶׁךְ וְתַרְבִּית** חַד שַׁוְּיוּהּ רַבָּנָן (ב"מ ס), וְלַעֲבֹר עָלָיו בִּשְׁנֵי לָאוִין, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:ל"ו). וּלְפִי פְּשׁוּטוֹ נִרְאֶה בְּעֵינַי כִּי הַנֶּשֶׁךְ הוּא שֶׁיַּלְוֶנּוּ מָנֶה לִתֵּן לוֹ בְּרִבִּיתוֹ חֲמֵשֶׁת שְׁקָלִים בְּכָל שָׁנָה. וְיִקָּרֵא כֵן בַּעֲבוּר כִּי אַחֲרִיתוֹ כְּנָחָשׁ יִשָּׁךְ, שֶׁמְּבַצְבֵּץ וְעוֹלֶה. הַתַּרְבִּית הוּא שֶׁיַּלְוֶנּוּ עַד זְמַן פְּלוֹנִי, וְאָז יִפְרָעֶנּוּ וְיִתֵּן לוֹ רִבִּית חֲמִשָּׁה שְׁקָלִים, וְאֵין בּוֹ רִבִּית אַחַר הַזְּמַן הַהוּא, כִּי זֶה אֵינֶנּוּ נוֹשֵׁךְ, שֶׁלֹּא יַעֲלֶה יוֹתֵר מִן הַסַּךְ הַהוּא, אֲבָל הוּא רִבִּית. וּלְכָךְ אָמַר (ויקרא כ"ה:ל"ז) "אֶת כַּסְפְּךָ לֹא תִתֵּן לוֹ בְּנֶשֶׁךְ וּבְמַרְבִּית לֹא תִתֵּן אָכְלֶךָ", כִּי הַמִּנְהָג לְהַלְווֹת אֶת הַכֶּסֶף בְּנֶשֶׁךְ, בְּכָל שָׁנָה יִתֵּן כָּךְ, וְהָאֹכֶל יַלְוֶנּוּ עַד הַקָּצִיר וְאָז יִפְרָעֶנּוּ מִגָּרְנוֹ בְּתוֹסֶפֶת קָצוּב:
@40 וְטַעַם **כְּשָׂכִיר כְּתוֹשָׁב** לֹא יִהְיֶה עִמְּךָ בְּבֵיתְךָ כְּעֶבֶד אֶלָּא כִּשְׂכִיר שָׁנָה, שֶׁהוּא הַנִּשְׂכָּר לַעֲבוֹדַת בְּנֵי חוֹרִין, וְלֹא יַכְבִּידוּ עָלָיו. אוֹ **כְּתוֹשָׁב** , שֶׁדֶּרֶךְ הַתּוֹשָׁבִים הַבָּאִים לָגוּר בָּאָרֶץ שֶׁיַּעַבְדוּ אֶת בַּעַל הַבַּיִת אֲשֶׁר הֵם מִתְגּוֹרְרִים עִמּוֹ לְרָצוֹן לָהֶם, כְּעִנְיַן יַעֲקֹב עִם לָבָן שֶׁאָמַר (בראשית כט טו), "הֲכִי אָחִי אַתָּה וַעֲבַדְתַּנִי חִנָּם הַגִּידָה לִּי מַה מַּשְׂכֻּרְתֶּךָ". וּבְתוֹרַת כֹּהֲנִים (פרק ז ג), "כְּשָׂכִיר" - מַה שָׂכִיר "בְּיוֹמוֹ תִּתֵּן שְׂכָרוֹ" (דברים כד טו) אַף זֶה בְּיוֹמוֹ תִּתֵּן שְׂכָרוֹ. "כְּתוֹשָׁב" - מַה תּוֹשָׁב "בַּטּוֹב לוֹ לֹא תּוֹנֶנּוּ" (שם כג יז) אַף זֶה בַּטּוֹב לוֹ לֹא תּוֹנֶנּוּ, "יִהְיֶה עִמָּךְ" - עִמָּךְ בְּמַאֲכָל עִמָּךְ בְּמִשְׁתֶּה עִמָּךְ בִּכְסוּת נְקִיָּה וְכוּ':
@47 **מִשְׁפַּחַת גֵּר** זֶה הַגּוֹי. כְּשֶׁהוּא אוֹמֵר "לְעֵקֶר" זֶה הַנִּמְכָּר לַע"ז עַצְמָהּ לִהְיוֹת לָהּ שַׁמָּשׁ, וְלֹא לֶאֱלֹהוּת אֶלָּא לַחְטֹב לָהּ עֵצִים וְלִשְׁאֹב לָהּ מַיִם, לְשׁוֹן רַשִׁ"י (רש"י על ויקרא כ"ה:מ"ז) מִתּוֹרַת כֹּהֲנִים (פרק ח א). וְאִם כֵּן יֹאמַר "אוֹ לְעֵקֶר וּמִשְׁפַּחַת גֵּר". וְקָרָא לַע"ז "עֵקֶר" בַּעֲבוּר שֶׁאָדָם חַיָּב לְשָׁרֵשׁ אַחֲרֶיהָ וּלְעָקְרָהּ. וְאוּנְקְלוֹס (תרגום אונקלוס על ויקרא כ"ה:מ"ז) תִּרְגֵּם "לְאַרְמַאי", וְהוּא הַנָּכוֹן, וְהִזְכִּיר הַכָּתוּב נִמְכָּר לַגֵּר הַתּוֹשָׁב עִמָּנוּ וְהַנִּמְכָּר לְעֵקֶר מִשְׁפַּחַת הַגֵּר שֶׁהוּא הַגּוֹי עַצְמוֹ, וְהוּא מִלְּשׁוֹן "עִקַּר שָׁרְשׁוֹהִי" (דניאל ד יב), וְאָמַר "מִשְׁפַּחַת גֵּר", שֶׁהַגֵּר וְהַתּוֹשָׁב שֶׁהִשִּׂיגָה יָדוֹ עִמָּנוּ הוּא סִבֵּב בָּאָח שֶׁמָּךְ עִמּוֹ שֶׁיִּמָּכֵר לְעֵקֶר מִשְׁפַּחְתּוֹ. וְצִוָּה הַכָּתוּב שֶׁתִּהְיֶה לוֹ גְּאֻלָּה, וְהִיא מִצְוַת עֲשֵׂה לְכָל יִשְׂרָאֵל שֶׁנִּגְאַל אוֹתוֹ, וְאַחַר כָּךְ (ויקרא כ"ה:מ"ט) צִוָּה בַּקְּרוֹבִים שֶׁהֵם קוֹדְמִים. וְטַעַם הַמִּצְוָה בָּרוּר, כְּדֵי שֶׁלֹּא יִטָּמַע וְיִלְמַד מִמַּעֲשֵׂיהֶם, כִּי בִּשְׁאָר הַנִּמְכָּרִים הַגְּאֻלָּה בַּקְּרוֹבִים רְשׁוּת, וּלְכָךְ אָמַר כָּאן (ויקרא כ"ה:נ"ה) "כִּי לִי בְנֵי יִשְׂרָאֵל עֲבָדִים עֲבָדַי הֵם", לוֹמַר אע"פ שֶׁאֵין הַגֵּר תּוֹשָׁב וְהָעֵקֶר חַיָּבִין בְּמִצְוַת הַיּוֹבֵל, לֹא יִקְנוּ אֶת עֲבָדַי לָהֶם לַעֲבָדִים:
@56 **לֹא תַעֲשׂוּ לָכֶם אֱלִילִם** כְּנֶגֶד זֶה הַנִּמְכָּר לְגוֹי הַכָּתוּב מְדַבֵּר, שֶׁלֹּא יֹאמַר הוֹאִיל וְרַבִּי עוֹבֵד עֲבוֹדָה זָרָה אַף אֲנִי אֶעֱבֹד עֲבוֹדָה זָרָה, הוֹאִיל וְרַבִּי מְגַלֶּה עֲרָיוֹת אַף אֲנִי אֲגַלֶּה עֲרָיוֹת, הוֹאִיל וְרַבִּי מְחַלֵּל שַׁבָּת אַף אֲנִי אֲחַלֵּל שַׁבָּת, תַּלְמוּד לוֹמַר "לֹא תַעֲשׂוּ לָכֶם אֱלִילִם אֶת שַׁבְּתֹתַי תִּשְׁמֹרוּ וּמִקְדָּשִׁי תִּירָאוּ", הִזְהִיר כֵּן הַכָּתוּב עַל הַמִּצְוֹת, לְשׁוֹן תּוֹרַת כֹּהֲנִים (פרק ט ו). וּפֵרוּשָׁהּ שֶׁהִזְכִּיר הַכָּתוּב עֲבוֹדָה זָרָה וְשַׁבָּת שֶׁיִּזָּהֵר בָּהֶן הָעֶבֶד הַנִּמְכָּר לְגוֹי, וּמוֹרָא הַמִּקְדָּשׁ שֶׁיָּבֹא שָׁם בָּרְגָלִים וְיִירָא מִמֶּנּוּ, וְהוּא הַדִּין לְכָל הַמִּצְוֹת. אֲבָל הִזְכִּיר אֵלֶּה שֶׁהֵן אָבוֹת לְלַמֵּד עַל כֻּלָּן. וְיֵשׁ גּוֹרְסִין "הִזְכִּיר (ס"א הזהיר) כָּאן" וְאִם הַגִּרְסָא כָּךְ רָמְזוּ שֶׁכָּל הַמִּצְוֹת בִּכְלַל הַשַּׁבָּת וְהַמִּקְדָּשׁ, וְהַמַּשְׂכִּיל יָבִין:
